  `frais_livraison_ht` decimal(15,2) DEFAULT 0.00,
  `total_general_ttc` decimal(15,2) GENERATED ALWAYS AS (`total_ttc` + `frais_livraison_ht` * (1 + 20 / 100)) STORED,
  `statut` enum('en_attente','confirmee','preparation','expediee','livree','annulee','remboursee') DEFAULT 'en_attente',
  `mode_paiement` varchar(50) DEFAULT NULL,
  `statut_paiement` enum('en_attente','paye','echoue','rembourse') DEFAULT 'en_attente',
  `transaction_id` varchar(255) DEFAULT NULL,
  `date_paiement` datetime DEFAULT NULL,
  `mode_livraison` varchar(50) DEFAULT 'standard',
  `date_livraison_prevue` datetime DEFAULT NULL,
  `date_livraison_reelle` datetime DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `ip_commande` varchar(45) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

