  `id_media` int(11) NOT NULL,
  `titre` varchar(255) DEFAULT NULL COMMENT 'Titre du média',
  `slug` varchar(255) DEFAULT NULL,
  `type` enum('image','video','audio','document','link','autre') NOT NULL COMMENT 'Type de média (link = lien externe)',
  `fichier` varchar(500) DEFAULT NULL COMMENT 'Chemin du fichier uploadé (pour types image, video, audio, document, autre)',
  `lien` varchar(500) DEFAULT NULL COMMENT 'URL externe (pour type link)',
  `miniature` varchar(500) DEFAULT NULL COMMENT 'Chemin de la miniature (optionnel)',
  `description` text DEFAULT NULL COMMENT 'Description du média',
  `description_fr` text DEFAULT NULL,
  `description_en` text DEFAULT NULL,
  `description_sw` text DEFAULT NULL,
  `categorie` varchar(100) DEFAULT NULL COMMENT 'Catégorie (ex: publicité, témoignage, produit)',
  `categorie_fr` varchar(100) DEFAULT NULL,
  `categorie_en` varchar(100) DEFAULT NULL,
  `categorie_sw` varchar(100) DEFAULT NULL,
  `date_media` date DEFAULT NULL COMMENT 'Date de création/prise du média',
  `credits` varchar(255) DEFAULT NULL COMMENT 'Crédits/auteur',
  `credits_fr` varchar(255) DEFAULT NULL,
  `credits_en` varchar(255) DEFAULT NULL,
  `credits_sw` varchar(255) DEFAULT NULL,
  `taille` int(11) DEFAULT NULL COMMENT 'Taille du fichier en octets (pour fichiers)',
  `mime_type` varchar(100) DEFAULT NULL COMMENT 'Type MIME (pour fichiers)',
  `duree` int(11) DEFAULT NULL COMMENT 'Durée en secondes',
  `bitrate` int(11) DEFAULT NULL,
  `sample_rate` int(11) DEFAULT NULL,
  `channels` tinyint(4) DEFAULT NULL,
  `waveform` varchar(500) DEFAULT NULL,
  `spectrogram` varchar(500) DEFAULT NULL,
  `waveform_data` longtext DEFAULT NULL,
  `metadata_id3` longtext DEFAULT NULL,
  `converted_versions` text DEFAULT NULL COMMENT 'Versions multi-bitrate au format JSON',
  `hls_playlist` varchar(255) DEFAULT NULL COMMENT 'Chemin playlist HLS',
  `est_actif` tinyint(1) DEFAULT 1 COMMENT '0 = caché, 1 = visible',
  `a_partager_reseaux` tinyint(1) DEFAULT 0 COMMENT '1 = à partager sur les réseaux sociaux',
  `message_reseaux` text DEFAULT NULL COMMENT 'Message personnalisé pour le partage',
  `message_reseaux_fr` text DEFAULT NULL,
  `message_reseaux_en` text DEFAULT NULL,
  `message_reseaux_sw` text DEFAULT NULL,
  `contenu_texte` text DEFAULT NULL COMMENT 'Contenu texte pour médias type texte',
  `contenu_texte_fr` text DEFAULT NULL,
  `contenu_texte_en` text DEFAULT NULL,
  `contenu_texte_sw` text DEFAULT NULL,
  `required_subscription_id` int(10) UNSIGNED DEFAULT NULL,
  `id_page_associee` int(11) DEFAULT NULL COMMENT 'Page associée (si applicable)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `is_for_whatsapp` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Partager sur WhatsApp',
  `is_for_website` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Publier sur le site web',
  `is_recording` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = enregistrement via micro',
  `sous_type` varchar(255) DEFAULT NULL,
  `telechargements` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

