INSERT INTO `advertise_product` (`id`, `category_id`, `main_image`, `title`, `title_fr`, `title_en`, `title_sw`, `slug`, `description`, `description_fr`, `description_en`, `description_ar`, `description_sw`, `price`, `is_active`, `in_vedette`, `price_request_count`, `created_at`, `updated_at`) VALUES
(1, 1, '2026033018513769caaa19b3818.jpeg', 'EXTRAIT ANTI-TUMORAL', 'Extrait Anti-Tumoral', 'Anti-Tumoral Extract', 'Dondoo la Kukabiliana na Tumori', 'extrait-anti-tumoral', '* Tumeurs \r\n* Nodules\r\n* Hypertrophie prostatiqie\r\n* Calculs et thromboses\r\n* Maladies rénales diverses\r\n* Infections virales, bactériennes et fongiques', '* Tumeurs\n* Nodules\n* Hypertrophie prostatique\n* Calculs et thromboses\n* Maladies rénales diverses\n* Infections virales, bactériennes et fongiques', '* Tumors\n* Nodules\n* Prostate hypertrophy\n* Stones and thrombosis\n* Various kidney diseases\n* Viral, bacterial and fungal infections', '* ???????\n* ????????\n* ???? ??????????\n* ??????? ????????\n* ????? ????? ????????\n* ?????????? ????????? ?????????? ????????', '* Tumors\n* Vinundu\n* Ukuzaji wa kibofu cha mkojo\n* Mawe na kuganda kwa damu\n* Magonjwa mbalimbali ya figo\n* Maambukizi ya virusi, bakteria na kuvu', '4$ = 12000fbu', 1, 1, 2, '2026-03-27 09:52:24', '2026-04-19 12:26:11'),
(2, 1, '2026033018504569caa9e537f6b.jpeg', 'DERMÉCUIR', 'Dermécur', 'Dermecuir', 'Dermecuir', 'dermcuir', '* Cheveux ternes et cassants\r\n* Alopécie (Chute de cheveux)\r\n* Boutons du visage/Acné\r\n* Vitiligo\r\n* Mycoses cutanées\r\n', '* Cheveux ternes et cassants\n* Alopécie (chute de cheveux)\n* Boutons du visage / Acné\n* Vitiligo\n* Mycoses cutanées', '* Dull and brittle hair\n* Alopecia (hair loss)\n* Facial pimples / Acne\n* Vitiligo\n* Skin mycoses', '* ??? ???? ???\n* ??????? (????? ?????)\n* ???? ????? / ?? ??????\n* ??????\n* ???????? ???????', '* Nywele zisizo na kipato na kukatika\n* Uparikaji wa nywele\n* Chunusi usoni\n* Vitiligo\n* Kuvu kwenye ngozi', '7$ = 21000fbu', 1, 1, 0, '2026-03-27 09:53:35', '2026-04-19 12:26:40'),
(3, 1, '2026033018500169caa9b94d12f.jpeg', 'RÉGÉNÉRATEUR PANCRÉATIQUE-INSULINE ', 'Régénérateur Pancréatique - Insuline', 'Pancreatic Regenerator - Insulin', 'Kirejesha Kongosho - Insulini', 'rgnrateur-pancratique-insuline', '* Diabète pamcréatique type 1 et 2\r\n* Complications diabétiques diverses', '* Diabète pancréatique type 1 et 2\n* Complications diabétiques diverses', '* Type 1 and 2 pancreatic diabetes\n* Various diabetic complications', '* ??? ?????? ?????????? ?? ????? 1 ? 2\n* ??????? ?????? ????????', '* Kisukari cha kongosho cha aina 1 na 2\n* Matatizo mbalimbali ya kisukari', '6$ = 18000fbu', 1, 1, 0, '2026-03-27 09:54:13', '2026-04-19 12:26:40'),
(4, 1, '2026033018440669caa85637673.jpeg', 'EXTRAITS ANTI-MICROBIENS (Les humains et les plantes)', 'Extraits Anti-Microbiens (Humains et Plantes)', 'Anti-Microbial Extracts (Humans and Plants)', 'Dondoo za Kuzuia Vijidudu (Binadamu na Mimea)', 'extraits-anti-microbiens-les-humains-et-les-plantes', '* Infections bactériennes\r\n* Infections virales\r\n* Infections fongiques', '* Infections bactériennes\n* Infections virales\n* Infections fongiques', '* Bacterial infections\n* Viral infections\n* Fungal infections', '* ?????????? ?????????\n* ?????????? ?????????\n* ?????????? ???????', '* Maambukizi ya bakteria\n* Maambukizi ya virusi\n* Maambukizi ya kuvu', '5$ = 15000fbu', 1, 0, 1, '2026-03-27 09:54:49', '2026-04-19 12:26:40'),
(5, 1, '2026033112085469cb9d36d5b1b.jpeg', 'TONIFIANT GENERAL+ ', 'Tonifiant Général +', 'General Tonic +', 'Toni ya Jumla +', 'tonifiant-general', '* Maladies oculaires\r\n* Neuropathies', '* Maladies oculaires\n* Neuropathies', '* Eye diseases\n* Neuropathies', '* ????? ??????\n* ?????????? ???????', '* Magonjwa ya macho\n* Ugonjwa wa mishipa', '7$ = 20000fbu', 1, 0, 3, '2026-03-31 10:08:54', '2026-04-19 12:26:40'),
(6, 1, '2026040212072069ce3fd863e9f.jpeg', 'LA LIBIDO', 'La Libido', 'The Libido', 'Libido', 'la-libido', '-Sécheresse vaginale et dégoût sexuel;\r\n-Baisse de la libido et impuossance sexuelle (Dysfonction érectile);\r\n-Diverses formes de stérilité masculine et féminine;\r\n\r\nLe produit induit la production des hormones liées à la stimulation la plus forte de la libido chez l\'homme et chez la femme: Gonadolibérine, Testostérone, LH, FSH, Estradiol, etc.);\r\n\r\nIl fait activement face au déséquilibre en neutransmetteurs responsables du maintien de la libido: Ocytocine, dopamine, sérotonine, et noradrénaline;\r\n\r\nIl stimule la production de la cyprine pour la lubrification vaginale, en vue de l\'extase séxuelle du couple.\r\n', '- Sécheresse vaginale et dégoût sexuel;\n- Baisse de la libido et impuissance sexuelle (Dysfonction érectile);\n- Diverses formes de stérilité masculine et féminine;\n\nLe produit induit la production des hormones liées à la stimulation la plus forte de la libido chez l\'homme et chez la femme : Gonadolibérine, Testostérone, LH, FSH, Estradiol, etc.);\n\nIl fait activement face au déséquilibre en neurotransmetteurs responsables du maintien de la libido : Ocytocine, dopamine, sérotonine, et noradrénaline;\n\nIl stimule la production de la cyprine pour la lubrification vaginale, en vue de l\'extase sexuelle du couple.', '- Vaginal dryness and sexual aversion;\n- Decreased libido and sexual impotence (erectile dysfunction);\n- Various forms of male and female sterility;\n\nThe product induces the production of hormones linked to the strongest libido stimulation in both men and women: Gonadoliberin, Testosterone, LH, FSH, Estradiol, etc.);\n\nIt actively counteracts the imbalance of neurotransmitters responsible for maintaining libido: Oxytocin, dopamine, serotonin, and norepinephrine;\n\nIt stimulates the production of vaginal fluid for lubrication, aiming at the couple\'s sexual ecstasy.', '- ???? ?????? ??????? ???????\n- ?????? ?????? ??????? ?????? ?????? (??? ????????)?\n- ????? ?????? ?? ????? ??? ?????? ????????\n\n???? ?????? ????? ????????? ???????? ????? ????? ?????? ??????? ??? ?????? ???????: ?????????????? ????????????? LH? FSH? ???????????? ????\n\n??? ????? ????? ?????? ??????? ?? ???????? ??????? ???????? ?? ?????? ??? ?????? ???????: ????????????? ?????????? ???????????? ???????????????\n\n???? ????? ???? ?????? ???????? ???? ????? ?????? ??????? ???????.', '- Ukavu wa uke na chuki ya ngono;\n- Kupungua kwa libido na ugumba wa ngono (kutofaulu kwa mwamba);\n- Aina mbalimbali za utasa kwa wanaume na wanawake;\n\nBidhaa hii huchochea uzalishaji wa homoni zinazohusiana na msisimko mkubwa wa libido kwa wanaume na wanawake: Gonadoliberini, Testosterone, LH, FSH, Estradioli, nk);\n\nInakabiliana kikamilifu na usawa wa nyurotransmita zinazohusika na kudumisha libido: Ocytosini, dopamini, serotonini, na norepinefrini;\n\nHuchochea uzalishaji wa maji ya uke kwa ulainishaji, kwa lengo la kufikia mshindo wa ngono kwa wanandoa.', '8$ = 24000FBU', 1, 0, 2, '2026-04-02 10:07:20', '2026-04-19 12:27:01');
