INSERT INTO `hero_slides` (`id`, `subtitle`, `title`, `description`, `background_image`, `button_primary_text`, `button_primary_icon`, `button_primary_link`, `button_secondary_text`, `button_secondary_icon`, `button_secondary_link`, `slide_order`, `is_active`, `created_at`, `updated_at`) VALUES
(5, 'Investissez dans l\'avenir', 'Opportunités d\'<span class=\"highlight\">investissement</span> phytomédicinales', 'Rejoignez NUFOTEC Phytomed dans notre mission de révolutionner la santé naturelle. Découvrez des opportunités d\'investissement uniques dans la recherche, l\'agriculture biologique et les solutions de bien-être innovantes.', '3b675831ac1cdfc26fcea1175c2fc852.jpg', 'Devenir investisseur', 'bx-right-arrow-alt', 'Investors-form', NULL, NULL, NULL, 1, 1, '2026-02-24 18:28:15', '2026-03-11 08:00:56'),
(6, 'Votre pharmacie naturelle', 'Notre marché de produits biologiques <span class=\"highlight\">en ligne</span>', 'Accédez à notre catalogue complet de produits phytomédicinaux, de compléments alimentaires et de solutions naturelles. Livraison rapide, paiement sécurisé et conseils personnalisés inclus.', '9c3f4ba0e80d7ef2f7d9423c1cc7bce2.jpg', 'Visiter la boutique', NULL, 'Home/Boutique', 'Nouveautés', NULL, 'Home/NewArrivals', 2, 1, '2026-02-24 18:28:15', '2026-02-25 14:41:56'),
(7, 'Soins de santé à distance', 'Téléconsultation en <span class=\"highlight\">phytothérapie</span> par des experts', 'Consultez nos experts en phytothérapie depuis chez vous. Diagnostic personnalisé, prescription naturelle et suivi complet par visioconférence sécurisée. Prise de rendez-vous sous 24 heures.', '8f8d130aaa695ce08cc5df05799a48f0.jpg', 'Prendre rendez-vous', NULL, 'Medicins', 'Nos experts', NULL, 'Home/Experts', 3, 1, '2026-02-24 18:28:15', '2026-02-25 14:41:13');
