INSERT INTO `produits` (`id_produit`, `id_categorie`, `nom_produit`, `slug`, `description_courte`, `description_longue`, `composition`, `indications`, `contre_indications`, `mode_emploi`, `presentation`, `conditionnement`, `prix_public`, `prix_grossiste`, `image_principale`, `galerie_images`, `fiche_technique_url`, `certifications`, `statut`, `date_lancement`, `est_vedette`, `ordre_affichage`, `est_actif`, `stock`, `stock_alerte`, `nb_favoris`, `currency`) VALUES
(1, 1, 'Carica papaya Extract', 'carica-papaya-extract', 'Standardized extract from Carica papaya leaves', 'Used in traditional medicine for various applications. Our GMP-compliant extraction process ensures consistent bioactive compound concentration.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026030314270469a6d39805b44.jpg', NULL, NULL, NULL, 'commercialise', NULL, 1, 1, 1, 0, 5, 1, '$'),
(2, 1, 'Aloe vera Extract', 'aloe-vera-extract', 'Pure Aloe vera extract', 'Cold-processed to preserve heat-sensitive compounds.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'commercialise', NULL, 0, 2, 1, 0, 5, 1, '$'),
(3, 2, 'Spirulina Capsules', 'spirulina-capsules', 'Organic spirulina in easy-to-take capsules', 'Rich in protein, vitamins, and minerals. Fortified with essential micronutrients.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'commercialise', NULL, 1, 1, 1, 0, 5, 0, '$'),
(4, 3, 'Fortified Soymilk Powder', 'fortified-soymilk-powder', 'Protein-rich plant milk powder', 'Fortified with essential vitamins and minerals for optimal nutrition. Ideal for children and pregnant women.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'commercialise', NULL, 1, 1, 1, 0, 5, 0, '$'),
(5, 4, 'Organic Tofu', 'organic-tofu', 'Vacuum-dried organic tofu', 'Long shelf-life without preservatives. Rich in protein and fortified with micronutrients.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'commercialise', NULL, 0, 1, 1, 0, 5, 0, '$'),
(6, 5, 'Moringa Powder', 'moringa-powder', 'Organic moringa leaf powder', 'Nutrient-dense superfood powder rich in vitamins, minerals and antioxidants.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'commercialise', NULL, 1, 1, 1, 0, 5, 0, '$'),
(7, 6, 'Organic Fertilizer - Liquid', 'organic-fertilizer-liquid', 'High-nutrient liquid organic fertilizer', 'Made from fermented organic materials (cow dung, pig dung, LAB strains), completely chemical-free.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'commercialise', NULL, 1, 1, 1, 0, 5, 0, '$'),
(8, 1, 'Artemisia annua Extract', 'artemisia-annua-extract', 'Extrait standardisé d\'Artemisia annua riche en artémisinine', 'Extrait hydro-alcoolique d\'Artemisia annua (armoise annuelle) standardisé à 98% d\'artémisinine. Utilisé traditionnellement pour ses propriétés antipaludiques et immunomodulatrices. Production GMP certifiée.', 'Artemisia annua (feuilles) 500mg, excipients qsp 1 capsule', 'Paludisme, infections parasitaires, renforcement immunitaire', 'Femmes enceintes, allaitement, enfants moins de 12 ans', '2 capsules 3 fois par jour avant les repas pendant 7 jours', 'Gélules végétales', 'Boîte de 60 gélules', 245.00, 180.00, '2026030319233669a719187fab0.jpg', NULL, NULL, NULL, 'commercialise', NULL, 1, 1, 1, 0, 5, 0, '$'),
(9, 1, 'Moringa oleifera Capsules', 'moringa-oleifera-capsules', 'Complément alimentaire à base de feuilles de Moringa bio', 'Moringa oleifera, l\'arbre miracle, concentré en vitamines, minéraux et antioxydants. Culture biologique contrôlée au Maroc. Séchage à basse température pour préserver les nutriments.', 'Moringa oleifera (feuilles en poudre) 400mg, enveloppe végétale', 'Fatigue, carences nutritionnelles, diabète, cholestérol', 'Aucune contre-indication connue', '2-4 gélules par jour avec un grand verre d\'eau', 'Gélules végétales', 'Boîte de 120 gélules', 189.00, 140.00, NULL, NULL, NULL, NULL, 'commercialise', NULL, 0, 2, 1, 0, 5, 0, '$'),
(10, 1, 'Nigella sativa Huile', 'nigella-sativa-huile', 'Huile de nigelle pure pressée à froid', 'Huile de graines de nigelle (Nigella sativa) 100% pure, pressée à froid pour conserver tous ses actifs. Riche en thymoquinone, acides gras essentiels et vitamine E.', 'Nigella sativa (huile de graines) 100%', 'Asthme, allergies, problèmes digestifs, renforcement immunitaire', 'Grossesse (sauf avis médical)', '1 cuillère à café par jour, pure ou dans du miel', 'Huile végétale', 'Flacon de 125ml', 156.00, 115.00, NULL, NULL, NULL, NULL, 'commercialise', NULL, 1, 3, 1, 0, 5, 1, '$'),
(11, 1, 'Harpagophytum Extract', 'harpagophytum-extract', 'Extrait de griffes du diable pour articulations', 'Extrait concentré de Harpagophytum procumbens (griffes du diable) standardisé en harpagosides. Anti-inflammatoire naturel pour le confort articulaire.', 'Harpagophytum (racine) 450mg standardisé à 2% harpagosides', 'Douleurs articulaires, arthrose, rhumatismes, lombalgies', 'Ulères gastriques, grossesse, calculs biliaires', '1 gélule 3 fois par jour pendant les repas', 'Gélules', 'Boîte de 90 gélules', 210.00, 155.00, NULL, NULL, NULL, NULL, 'commercialise', NULL, 0, 4, 1, 0, 5, 0, '$'),
(12, 1, 'Echinacea purpurea Complex', 'echinacea-purpurea-complex', 'Complexe immunostimulant à base d\'Echinacea', 'Association synergique d\'Echinacea purpurea, Echinacea angustifolia et vitamine C naturelle. Stimulation des défenses naturelles de l\'organisme.', 'Echinacea purpurea 200mg, E. angustifolia 100mg, Vit C 80mg', 'Prévention et traitement des infections respiratoires, grippe', 'Auto-immunité, maladies auto-immunes, grossesse', '2 gélules matin et soir pendant 10 jours', 'Gélules', 'Boîte de 60 gélules', 175.00, 130.00, NULL, NULL, NULL, NULL, 'commercialise', NULL, 0, 5, 1, 0, 5, 0, '$'),
(13, 1, 'Ginkgo biloba Standardisé', 'ginkgo-biloba-standardise', 'Extrait de Ginkgo biloba pour la mémoire et circulation', 'Extrait de feuilles de Ginkgo biloba standardisé à 24% de flavonoïdes glycosides et 6% de terpènes lactones. Améliore la circulation cérébrale et périphérique.', 'Ginkgo biloba (extrait sec) 120mg standardisé', 'Troubles de la mémoire, vertiges, acouphènes, jambes lourdes', 'Anticoagulants, avant chirurgie, épilepsie', '1 comprimé matin et soir avec les repas', 'Comprimés', 'Boîte de 60 comprimés', 198.00, 145.00, NULL, NULL, NULL, NULL, 'commercialise', NULL, 1, 6, 1, 0, 5, 0, '$'),
(14, 1, 'Valeriana officinalis Forte', 'valeriana-officinalis-forte', 'Valériane forte pour sommeil et anxiété', 'Racines de Valeriana officinalis concentrées, standardisées en acides valéréniques. Aide naturelle au sommeil et gestion du stress.', 'Valeriana officinalis (racine) 500mg standardisé à 0,8% acides valéréniques', 'Troubles du sommeil, anxiété légère, stress nerveux', 'Dépression sévère, traitement sedatifs, conduite automobile', '1-2 gélules 30 min avant le coucher', 'Gélules', 'Boîte de 60 gélules', 165.00, 120.00, NULL, NULL, NULL, NULL, 'commercialise', NULL, 0, 7, 1, 0, 5, 0, '$'),
(15, 1, 'Curcuma longa Bio + Poivre noir', 'curcuma-longa-bio-poivre', 'Curcuma bio amplifié au poivre noir pour absorption', 'Curcuma biologique du Maroc associé au poivre noir (pipérine) pour maximiser l\'absorption de la curcumine. Puissant anti-inflammatoire naturel.', 'Curcuma (rhizome) 500mg, Poivre noir 5mg (95% pipérine)', 'Inflammations chroniques, douleurs articulaires, digestion', 'Calculs biliaires, anticoagulants, grossesse', '1-2 gélules par jour avec repas gras', 'Gélules gastro-résistantes', 'Boîte de 120 gélules', 225.00, 165.00, NULL, NULL, NULL, NULL, 'commercialise', NULL, 1, 8, 1, 0, 5, 0, '$'),
(16, 1, 'Allium sativum Ail Noir', 'allium-sativum-ail-noir', 'Ail noir fermenté antioxydant et cardiovasculaire', 'Ail blanc fermenté selon processus traditionnel coréen pendant 30 jours. Riche en S-allylcystéine, sans odeur, goût fruité.', 'Allium sativum (ail noir fermenté) 600mg', 'Hypertension, cholestérol, circulation sanguine, antioxydant', 'Anticoagulants, avant chirurgie', '2-3 gélules par jour avant les repas', 'Gélules', 'Boîte de 90 gélules', 280.00, 210.00, NULL, NULL, NULL, NULL, 'commercialise', NULL, 0, 9, 1, 0, 5, 0, '$'),
(17, 1, 'Cinchona calisaya Quinine', 'cinchona-calisaya-quinine', 'Extrait de quinquina naturel antipaludique', 'Ecorce de Cinchona calisaya riche en quinine naturelle. Traditionnellement utilisée contre le paludisme et les fièvres intermittentes.', 'Cinchona calisaya (écorce) 300mg, quinine naturelle 60mg', 'Fièvres, paludisme, crampes nocturnes', 'Grossesse, myasthénie, antécédents thrombose', '1 gélule 2-3 fois par jour (sur prescription médicale)', 'Gélules', 'Boîte de 60 gélules (sur ordonnance)', 195.00, 145.00, NULL, NULL, NULL, NULL, 'commercialise', NULL, 0, 10, 1, 0, 5, 0, '$');
