(15, 'Quality loss, spoilage, inefficiencies', 'GMP-compliant processing, cold storage, optimized logistics, HACCP protocols', 'Opérationnel', 'moyen', 0, NULL, '2026-02-26 00:01:52', NULL, NULL),
(16, 'Worker illness, labor shortage', 'Occupational health programs, sanitation, training, insurance coverage', 'Social', 'faible', 0, NULL, '2026-02-26 00:01:52', NULL, NULL),
(17, 'Crop, machinery, or input theft and vandalism', 'Security wall fence, security wire fence, security guards, CCTV cameras, community engagement', 'Sécurité', 'moyen', 0, NULL, '2026-02-26 00:01:52', NULL, NULL),
(18, 'Unexpected losses (climate, market, fire)', 'Crop and asset insurance, contingency funds, prudent financial planning', 'Financier', 'moyen', 0, NULL, '2026-02-26 00:01:52', NULL, NULL),
(19, 'Political and Regulatory Risks', 'Proactive engagement with regulators, legal advisory, and diversification across markets', 'Réglementaire', 'moyen', 0, NULL, '2026-02-26 00:01:52', NULL, NULL),
(20, 'Supply Chain Risks', 'Contractual suppliers, local cooperatives, quality pre-testing, and multiple sourcing options', 'Supply Chain', 'moyen', 0, NULL, '2026-02-26 00:01:52', NULL, NULL),
(21, 'Governance and Capital Risks', 'Milestone-based disbursement, segregated accounts, IFRS-aligned audits, and investor oversight', 'Gouvernance', 'faible', 0, NULL, '2026-02-26 00:01:52', NULL, NULL),
(22, 'Market Access Risks', 'Pre-offtake agreements, digital traceability, and diversified distribution channels', 'Marché', 'moyen', 0, NULL, '2026-02-26 00:01:52', NULL, NULL);
