INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(38, 1, 'image_texte', 'Consultez un professionnel de santé, où que vous soyez.', 'Consultez un professionnel de santé, où que vous soyez.', 'Consult a healthcare professional, wherever you are.', 'Wasiliana na mtaalamu wa afya, popote ulipo.', 'Téléconsultation simple, rapide et sécurisée avec des agents qualifiés à votre service.', 'Téléconsultation simple, rapide et sécurisée avec des agents qualifiés à votre service.', 'Simple, fast and secure teleconsultation with qualified agents at your service.', 'Ushauri wa kijijini rahisi, wa haraka na salama kwa mawakala waliohitimu walioko kwenye huduma yako.', '<p>Acc&eacute;dez &agrave; des services de t&eacute;l&eacute;consultation fiables et s&eacute;curis&eacute;s en quelques clics. Notre plateforme vous met en relation avec des agents qualifi&eacute;s et des professionnels de sant&eacute; disponibles pour r&eacute;pondre rapidement et efficacement &agrave; vos besoins. Que vous ayez besoin d\'un avis m&eacute;dical, d\'un suivi ou de conseils, nous vous accompagnons &agrave; distance avec confidentialit&eacute; et professionnalisme. &Eacute;vitez les d&eacute;placements inutiles et les longues attentes : r&eacute;servez votre rendez-vous en ligne et consultez depuis chez vous, &agrave; tout moment. Notre priorit&eacute; est de vous offrir un service accessible, humain et s&eacute;curis&eacute;.</p>', '<p>Acc&eacute;dez &agrave; des services de t&eacute;l&eacute;consultation fiables et s&eacute;curis&eacute;s en quelques clics. Notre plateforme vous met en relation avec des agents qualifi&eacute;s et des professionnels de sant&eacute; disponibles pour r&eacute;pondre rapidement et efficacement &agrave; vos besoins. Que vous ayez besoin d\'un avis m&eacute;dical, d\'un suivi ou de conseils, nous vous accompagnons &agrave; distance avec confidentialit&eacute; et professionnalisme. &Eacute;vitez les d&eacute;placements inutiles et les longues attentes : r&eacute;servez votre rendez-vous en ligne et consultez depuis chez vous, &agrave; tout moment. Notre priorit&eacute; est de vous offrir un service accessible, humain et s&eacute;curis&eacute;.</p>', '<p>Access reliable and secure teleconsultation services in just a few clicks. Our platform connects you with qualified agents and healthcare professionals available to respond quickly and effectively to your needs. Whether you need medical advice, follow-up or guidance, we support you remotely with confidentiality and professionalism. Avoid unnecessary travel and long waits: book your appointment online and consult from home, at any time. Our priority is to offer you an accessible, human and secure service.</p>', '<p>Pata huduma za ushauri wa kijijini za kuaminika na salama kwa kubofya chache. Jukwaa letu linakuunganisha na mawakala waliohitimu na wataalamu wa afya walio tayari kukidhi mahitaji yako haraka na kwa ufanisi. Iwe unahitaji ushauri wa kitiba, ufuatiliaji au ushauri, tunakusaidia kwa mbali kwa usiri na uwelekezi. Epuka safari zisizo za lazima na kusubiri kwa muda mrefu: weka miadi yako mtandaoni na wasiliana kutoka nyumbani, wakati wowote. Kipaumbele chetu ni kukupa huduma inayopatikana, ya kibinadamu na salama.</p>', '/attachments/Sections/2026032420105069c2d3aa05c58.jpg', 0, 'Prendre Rendez-Vous', 'Prendre Rendez-Vous', 'Book an Appointment', 'Weka Miadi', 'Medicins', 3, '2026-03-01 15:44:36', 'primary', NULL, '2026-03-26 07:58:44', NULL, 1),
(58, 2, 'hero', '', NULL, NULL, NULL, 'NUFOTEC-PHYTOMED INDUSTRIES', NULL, NULL, NULL, '', NULL, NULL, NULL, '/attachments/Sections/2026030119144869a47408b4280.jpg', 0, '', NULL, NULL, NULL, '', 1, '2026-03-01 15:44:36', '', NULL, '2026-03-24 18:23:58', NULL, 1),
(111, 3, 'texte', 'Contexte et justification stratégique', 'Contexte et justification stratégique', 'Context and strategic justification', 'Muktadha na uhalali wa kimkakati', 'Contexte et justification stratégique', 'Contexte et justification stratégique', 'Context and strategic justification', 'Muktadha na uhalali wa kimkakati', '<p class=\"MsoNormal\" style=\"margin: 0cm 3.75pt .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Le Burundi, comme de nombreuses nations africaines, est dotée d\'une riche biodiversité de plantes médicinales et d\'un fort héritage culturel d\'utilisation de la médecine traditionnelle. Cependant, le secteur des Médecines Traditionnelles, Complémentaires et Alternatives (MTCAs) reste largement sous-développé, caractérisé par des pratiques rudimentaires, un manque de standardisation, un soutien minimal à la recherche et l\'absence d\'infrastructures de fabrication modernes. Malgré une volonté politique croissante, la reconnaissance par le ministère de la Santé et la mise en place d\'organismes de réglementation tels que la ZAMRA, le pays manque encore de la capacité technologique nécessaire pour transformer les connaissances traditionnelles en produits de santé de haute qualité, sûrs et standardisés.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .65pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">NUFOTEC-PHYTOMED Industries est structurée, via son installation NUFOTEC-PHYTOMED Industries, comme une plateforme de fabrication agro-biotechnologique et phytopharmaceutique intégrée verticalement, alignée sur les BPF et aux normes ISO, conçue pour capturer la demande de croissance élevée pour les produits de santé préventifs et thérapeutiques à base de plantes sur les marchés domestiques et régionaux. En faisant passer la culture biologique commerciale de 90 hectares à plus de 2 000 hectares de cultures médicinales et de cultures riches en nutriments à haute valeur ajoutée, y compris l\'Aloe vera et la Carica papaya, et en déployant plus de 40 millions USD dans des infrastructures de transformation avancées, des environnements de fabrication en salle blanche, des laboratoires phytochimiques et microbiologiques et des systèmes qualité certifiés ISO, NUFOTEC assure la traçabilité des matières premières, établit de solides barrières à l\'entrée, optimise les marges de valeur ajoutée et réduit la dépendance aux importations régionales. L\'architecture de produits diversifiée &ndash; couvrant les MTCAs standardisées, les nutraceutiques, les aliments fonctionnels fortifiés clean-label, les engrais organiques riches en nutriments, les phytomédicines et phytopharmaceutiques cliniquement validés &ndash; crée des flux de revenus superposés avec une génération de trésorerie précoce et un positionnement phytopharmaceutique à long terme à haute marge, visant un chiffre d\'affaires annuel de plusieurs millions de dollars, une performance EBITDA durable et une expansion exportable à l\'échelle d\'ici 2031.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .9pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">L\'installation NUFOTEC-PHYTOMED INDUSTRIES émerge comme l\'une des principales initiatives privées zambiennes visant à mettre en œuvre des solutions industrielles automatisées, entièrement intégrées et de pointe dans le secteur des herbes et nutraceutiques. L\'entreprise a adopté un système de ligne de production clé en main automatisé et personnalisé, rare, conforme aux BPF et aux normes ISO pour l\'extraction, l\'encapsulation et la mise en comprimés d\'API (Principes Actifs Pharmaceutiques) à base de plantes. Cette configuration industrielle complexe et automatisée ―<em style=\"mso-bidi-font-style: normal;\"> TURNKEY ULTRASOUND-ASSISTED EXTRACTION (UAE), CAPSULE PRODUCTION AND TABLETING LINE SYSTEM</em>‖ combine trois techniques de transformation avancées :<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .05pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">1)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Procédé d\'extraction et de purification phytochimique &ndash; Traitement post-récolte, dégraissage éventuel, concentration, purification éventuelle, séchage sous vide et conditionnement de l\'extrait pour stockage ;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">2)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Procédé de fabrication de gélules &ndash; Encapsulation, remplissage des flacons, capsulage et scellage, étiquetage des flacons, mise en carton des flacons, insertion de la notice et scellage et emballage en caisse de 15 flacons ;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">3)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Procédé de fabrication de comprimés &ndash; Mélange d\'extrait sec, granulation, séchage sous vide éventuel, sécheur à lit fluidisé, compression des comprimés, enrobage des comprimés, remplissage des flacons, capsulage, scellage des flacons, étiquetage des flacons, mise en carton des flacons, insertion de la notice ainsi que l\'emballage en caisse de 15 flacons.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Le système de ligne fonctionne à des températures réduites (40&ndash;60°C) pour préserver les principes actifs pharmaceutiques thermosensibles (composés bioactifs) ciblés pour développer des phytomédicaments sûrs et efficaces, des nutraceutiques, des aliments santé fortifiés riches en nutriments et des engrais organiques riches en nutriments &ndash; une technologie de pointe sans précédent dans le secteur des MTCAs/phytomédecine en Zambie.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>', '<p class=\"MsoNormal\" style=\"margin: 0cm 3.75pt .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Le Burundi, comme de nombreuses nations africaines, est dotée d\'une riche biodiversité de plantes médicinales et d\'un fort héritage culturel d\'utilisation de la médecine traditionnelle. Cependant, le secteur des Médecines Traditionnelles, Complémentaires et Alternatives (MTCAs) reste largement sous-développé, caractérisé par des pratiques rudimentaires, un manque de standardisation, un soutien minimal à la recherche et l\'absence d\'infrastructures de fabrication modernes. Malgré une volonté politique croissante, la reconnaissance par le ministère de la Santé et la mise en place d\'organismes de réglementation tels que la ZAMRA, le pays manque encore de la capacité technologique nécessaire pour transformer les connaissances traditionnelles en produits de santé de haute qualité, sûrs et standardisés.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .65pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">NUFOTEC-PHYTOMED Industries est structurée, via son installation NUFOTEC-PHYTOMED Industries, comme une plateforme de fabrication agro-biotechnologique et phytopharmaceutique intégrée verticalement, alignée sur les BPF et aux normes ISO, conçue pour capturer la demande de croissance élevée pour les produits de santé préventifs et thérapeutiques à base de plantes sur les marchés domestiques et régionaux. En faisant passer la culture biologique commerciale de 90 hectares à plus de 2 000 hectares de cultures médicinales et de cultures riches en nutriments à haute valeur ajoutée, y compris l\'Aloe vera et la Carica papaya, et en déployant plus de 40 millions USD dans des infrastructures de transformation avancées, des environnements de fabrication en salle blanche, des laboratoires phytochimiques et microbiologiques et des systèmes qualité certifiés ISO, NUFOTEC assure la traçabilité des matières premières, établit de solides barrières à l\'entrée, optimise les marges de valeur ajoutée et réduit la dépendance aux importations régionales. L\'architecture de produits diversifiée &ndash; couvrant les MTCAs standardisées, les nutraceutiques, les aliments fonctionnels fortifiés clean-label, les engrais organiques riches en nutriments, les phytomédicines et phytopharmaceutiques cliniquement validés &ndash; crée des flux de revenus superposés avec une génération de trésorerie précoce et un positionnement phytopharmaceutique à long terme à haute marge, visant un chiffre d\'affaires annuel de plusieurs millions de dollars, une performance EBITDA durable et une expansion exportable à l\'échelle d\'ici 2031.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .9pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">L\'installation NUFOTEC-PHYTOMED INDUSTRIES émerge comme l\'une des principales initiatives privées zambiennes visant à mettre en œuvre des solutions industrielles automatisées, entièrement intégrées et de pointe dans le secteur des herbes et nutraceutiques. L\'entreprise a adopté un système de ligne de production clé en main automatisé et personnalisé, rare, conforme aux BPF et aux normes ISO pour l\'extraction, l\'encapsulation et la mise en comprimés d\'API (Principes Actifs Pharmaceutiques) à base de plantes. Cette configuration industrielle complexe et automatisée ―<em style=\"mso-bidi-font-style: normal;\"> TURNKEY ULTRASOUND-ASSISTED EXTRACTION (UAE), CAPSULE PRODUCTION AND TABLETING LINE SYSTEM</em>‖ combine trois techniques de transformation avancées :<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .05pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">1)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Procédé d\'extraction et de purification phytochimique &ndash; Traitement post-récolte, dégraissage éventuel, concentration, purification éventuelle, séchage sous vide et conditionnement de l\'extrait pour stockage ;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">2)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Procédé de fabrication de gélules &ndash; Encapsulation, remplissage des flacons, capsulage et scellage, étiquetage des flacons, mise en carton des flacons, insertion de la notice et scellage et emballage en caisse de 15 flacons ;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">3)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Procédé de fabrication de comprimés &ndash; Mélange d\'extrait sec, granulation, séchage sous vide éventuel, sécheur à lit fluidisé, compression des comprimés, enrobage des comprimés, remplissage des flacons, capsulage, scellage des flacons, étiquetage des flacons, mise en carton des flacons, insertion de la notice ainsi que l\'emballage en caisse de 15 flacons.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Le système de ligne fonctionne à des températures réduites (40&ndash;60°C) pour préserver les principes actifs pharmaceutiques thermosensibles (composés bioactifs) ciblés pour développer des phytomédicaments sûrs et efficaces, des nutraceutiques, des aliments santé fortifiés riches en nutriments et des engrais organiques riches en nutriments &ndash; une technologie de pointe sans précédent dans le secteur des MTCAs/phytomédecine en Zambie.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>', '<p class=\"MsoNormal\" style=\"margin: 0cm 3.75pt .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Burundi, like many African nations, is endowed with rich biodiversity of medicinal plants and a strong cultural heritage of using traditional medicine. However, the sector of Traditional, Complementary and Alternative Medicines (TCAMs) remains largely underdeveloped, characterized by rudimentary practices, lack of standardization, minimal research support and lack of modern manufacturing infrastructure. Despite growing political will, recognition by the Ministry of Health and the establishment of regulatory bodies such as ZAMRA, the country still lacks the technological capacity needed to transform traditional knowledge into high-quality, safe and standardized health products.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .65pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">NUFOTEC-PHYTOMED Industries is structured, through its NUFOTEC-PHYTOMED Industries facility, as a vertically integrated agro-biotechnological and phytopharmaceutical manufacturing platform, aligned with GMP and ISO standards, designed to capture the high growth demand for preventive and therapeutic plant-based health products in domestic and regional markets. By expanding commercial organic farming from 90 hectares to over 2,000 hectares of medicinal and high-value nutrient-rich crops, including Aloe vera and Carica papaya, and deploying over USD 40 million in advanced processing infrastructure, cleanroom manufacturing environments, phytochemical and microbiological laboratories and ISO certified quality systems, NUFOTEC ensures raw material traceability, establishes strong entry barriers, optimizes value-added margins and reduces dependence on regional imports. The diversified product architecture – covering standardized TCAMs, nutraceuticals, clean-label fortified functional foods, nutrient-rich organic fertilizers, clinically validated phytomedicines and phytopharmaceuticals – creates stacked revenue streams with early cash generation and long-term high-margin phytopharmaceutical positioning, aiming for several million USD annual turnover, sustainable EBITDA performance and scalable export expansion by 2031.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .9pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">The NUFOTEC-PHYTOMED INDUSTRIES facility emerges as one of the main Zambian private initiatives to implement automated, fully integrated and cutting-edge industrial solutions in the herbs and nutraceuticals sector. The company has adopted a rare, customized, automated turnkey production line system compliant with GMP and ISO standards for the extraction, encapsulation and tableting of plant-based Active Pharmaceutical Ingredients (APIs). This complex and automated industrial configuration ―TURNKEY ULTRASOUND-ASSISTED EXTRACTION (UAE), CAPSULE PRODUCTION AND TABLETING LINE SYSTEM‖ combines three advanced processing techniques:<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .05pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">1)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Phytochemical extraction and purification process – Post-harvest treatment, possible degreasing, concentration, possible purification, vacuum drying and packaging of the extract for storage;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">2)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Capsule manufacturing process – Encapsulation, bottle filling, capping and sealing, bottle labeling, bottle boxing, leaflet insertion and sealing and packing in a case of 15 bottles;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">3)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Tablet manufacturing process – Dry extract mixing, granulation, possible vacuum drying, fluid bed dryer, tablet compression, tablet coating, bottle filling, capping, bottle sealing, bottle labeling, bottle boxing, leaflet insertion and packaging in a case of 15 bottles.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">The line system operates at reduced temperatures (40–60°C) to preserve thermosensitive pharmaceutical active ingredients (bioactive compounds) targeted to develop safe and effective phytomedicines, nutraceuticals, nutrient-rich fortified health foods and nutrient-rich organic fertilizers – a cutting-edge technology unprecedented in the TCAMs/phytomedicine sector in Zambia.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>', '<p class=\"MsoNormal\" style=\"margin: 0cm 3.75pt .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Burundi, kama mataifa mengi ya Kiafrika, ina bayoanuwai tajiri ya mimea ya dawa na urithi thabiti wa kitamaduni wa matumizi ya dawa za jadi. Hata hivyo, sekta ya Dawa za Jadi, Ziada na Mbadala (TCAMs) bado haijaendelezwa kwa kiasi kikubwa, inayojulikana kwa mazoea ya kienyeji, ukosefu wa usanifishaji, msaada mdogo wa utafiti na ukosefu wa miundombinu ya kisasa ya utengenezaji. Licha ya nia inayoongezeka ya kisiasa, kutambuliwa na Wizara ya Afya na kuanzishwa kwa vyombo vya udhibiti kama vile ZAMRA, nchi bado inakosa uwezo wa kiteknolojia unaohitajika kubadilisha maarifa ya jadi kuwa bidhaa za afya za ubora wa juu, salama na sanifu.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .65pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">NUFOTEC-PHYTOMED Industries imeundwa, kupitia kituo chake cha NUFOTEC-PHYTOMED Industries, kama jukwaa la utengenezaji wa kilimo-bioteknolojia na dawa za mimea lililojumuishwa kiwima, linalolingana na viwango vya GMP na ISO, iliyoundwa kunyanyua mahitaji ya ukuaji wa juu wa bidhaa za afya za kuzuia na za matibabu zinazotokana na mimea katika masoko ya ndani na ya kikanda. Kwa kupanua kilimo cha kibiashara cha kikaboni kutoka hekta 90 hadi zaidi ya hekta 2,000 za mimea ya dawa na mazao yenye virutubisho vya thamani ya juu, ikiwa ni pamoja na Aloe vera na Carica papaya, na kupeleka zaidi ya USD milioni 40 katika miundombinu ya hali ya juu ya usindikaji, mazingira ya utengenezaji wa vyumba safi, maabara za fitokemikali na kibiolojia na mifumo ya ubora iliyoidhinishwa na ISO, NUFOTEC inahakikisha ufuatiliaji wa malighafi, inaweka vizuizi vikali vya kuingia, inaboresha ukingo wa thamani iliyoongezwa na kupunguza utegemezi wa uagizaji kutoka kikanda. Muundo wa bidhaa uliobadilishana – unaojumuisha TCAMs sanifu, virutubisho, vyakula vya kazi vilivyoimarishwa lebo-safi, mbolea za kikaboni zenye virutubisho vingi, dawa za mimea na dawa za mimea zilizothibitishwa kikliniki – huunda mtiririko wa mapato yaliyowekwa juu na uzalishaji wa mapema wa fedha na msimamo wa muda mrefu wa dawa za mimea wenye kiwango cha juu cha faida, ukilenga mauzo ya kila mwaka ya milioni kadhaa za USD, utendaji endelevu wa EBITDA na upanuzi wa mauzo ya nje unaoweza kuongezeka kufikia 2031.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .9pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Kituo cha NUFOTEC-PHYTOMED INDUSTRIES kinaibuka kama mojawapo ya mipango binafsi mikuu ya Zambia ya kutekeleza suluhisho za viwandani za kiotomatiki, zilizounganishwa kikamilifu na za kisasa katika sekta ya mimea na virutubisho. Kampuni imepitisha mfumo wa laini ya uzalishaji wa turnkey uliobinafsishwa, wa kiotomatiki, nadra, unaolingana na viwango vya GMP na ISO kwa uchimbaji, uwekaji kapsuli na utengenezaji wa vidonge vya Viambatanisho Amilifu vya Dawa (APIs) vinavyotokana na mimea. Usanidi huu tata na wa kiotomatiki wa kiviwanda ―TURNKEY ULTRASOUND-ASSISTED EXTRACTION (UAE), CAPSULE PRODUCTION AND TABLETING LINE SYSTEM‖ unachanganya mbinu tatu za hali ya juu za usindikaji:<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .05pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">1)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Mchakato wa uchimbaji na utakaso wa fitokemikali – Matibabu ya baada ya kuvuna, uondoaji wa mafuta iwezekanavyo, ukolezi, utakaso iwezekanavyo, ukaushaji wa utupu na ufungaji wa dondoo kwa uhifadhi;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">2)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Mchakato wa utengenezaji wa kapsuli – Uwekaji kapsuli, kujaza chupa, kufunga na kuziba, kuweka lebo kwenye chupa, kuweka kwenye sanduku la chupa, kuingiza kipeperushi na kuziba na kufungasha kwenye sanduku la chupa 15;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">3)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Mchakato wa utengenezaji wa vidonge – Kuchanganya dondoo kavu, uundaji wa chembe, ukaushaji wa utupu iwezekanavyo, kikausha cha kitanda cha maji, mgandamizo wa vidonge, upako wa vidonge, kujaza chupa, kufunga, kuziba chupa, kuweka lebo kwenye chupa, kuweka kwenye sanduku la chupa, kuingiza kipeperushi na ufungaji kwenye sanduku la chupa 15.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Mfumo wa laini hufanya kazi kwa joto la chini (40–60°C) ili kuhifadhi viambatanisho amilifu vya dawa vinavyohisi joto (viumbe hai) vinavyolengwa kuunda dawa za mimea salama na bora, virutubisho, vyakula vya afya vilivyoimarishwa vyenye virutubisho vingi na mbolea za kikaboni zenye virutubisho vingi – teknolojia ya kisasa isiyo na kifani katika sekta ya TCAMs/dawa za mimea nchini Zambia.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>', NULL, 0, '', '', NULL, NULL, '', 1, '2026-03-01 15:44:36', '', NULL, '2026-03-24 18:25:16', NULL, 1);
INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(112, 4, 'texte', 'ESG et durabilité', 'ESG et durabilité', 'ESG and sustainability', 'ESG na uendelevu', '', '', '', '', '<h2 style=\"margin-left: -0.25pt; padding-left: 120px;\"><span style=\"font-size: 18pt;\">(1)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Gouvernance, conformité et transparence</span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<h3 class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 80px;\"><span style=\"font-size: 14pt;\">NUFOTEC s\'engage en faveur d\'une gouvernance d\'entreprise solide, d\'une conformité réglementaire et d\'une transparence financière en tant que piliers fondamentaux d\'une croissance industrielle durable.<strong style=\"mso-bidi-font-weight: normal;\"> </strong>Le déploiement de plus de 40 millions USD en capital d\'amorçage donne la priorité aux infrastructures conformes aux BPF (Bonnes Pratiques de Fabrication), aux systèmes de certification ISO (<span style=\"line-height: 103%;\">ISO 9001, 22000, 14001, 45001 et 14644</span>), à la tenue d\'audits financiers indépendants annuels, à la production de rapports sur les performances ESG (Environnementales, Sociales et de Gouvernance), à la supervision des risques et aux structures de gouvernance au niveau du conseil d\'administration, garantissant ainsi la responsabilité et l\'intégrité institutionnelle.<strong style=\"mso-bidi-font-weight: normal;\"> </strong></span></h3>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<h5 class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 320px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><em><span style=\"font-size: 14pt;\">Engagements en matière de gouvernance :</span></em></span></h5>\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]--><strong><span style=\"font-family: georgia, palatino, serif;\">Mise en œuvre complète des BPF et documentation</span></strong></span></em></span></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->Achèvement de la feuille de route de certification ISO</span></em></span></strong></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->Audits financiers indépendants annuels</span></em></span></strong></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->Suivi et rapport des performances ESG</span></em></span></strong></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->Systèmes structurés de conformité et de gestion des risques</span></em></span></strong></li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<h2 style=\"margin-left: -0.25pt; padding-left: 80px;\"><span style=\"font-size: 18pt;\">(2)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Supervision institutionnelle et responsabilité</span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\">La société NUFOTEC opère selon un modèle de gouvernance d\'entreprise structuré qui garantit :</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.55pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Une séparation claire entre les actionnaires, le Conseil d\'administration et la Direction Générale</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.4pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Des responsabilités fiduciaires définies et des cadres de délégation de pouvoir</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.4pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Une expertise consultative indépendante en sciences réglementaires, finances, ESG et gestion des risques</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.15pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Une supervision structurée par le conseil d\'administration de la stratégie, de la conformité et de l\'allocation du capital</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\">Ce cadre de gouvernance s\'aligne sur les meilleures pratiques internationales reconnues par des institutions telles que la Société Financière Internationale et la Banque mondiale.</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 200px;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<h2 style=\"margin-left: -0.25pt; padding-left: 80px;\"><span style=\"font-size: 18pt;\">(2) Conformité réglementaire, assurance qualité et autorisations</span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\">NUFOTEC construit un écosystème de conformité intégré aligné sur les normes internationales reconnues, y compris mais sans s\'y limiter :</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.4pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 9001 - Système de Management de la Qualité</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.4pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 22000 - Sécurité des Denrées Alimentaires</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.5pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 14001 - Gouvernance Environnementale et Durabilité</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.3pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 45001 - Santé & Sécurité au Travail</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 15.35pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 14644 - Qualification des Salles Blanches<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong></p>\r\n<ul>\r\n<li style=\"list-style-type: none;\">\r\n<ul>\r\n<li style=\"list-style-type: none;\">\r\n<ul>\r\n<li style=\"list-style-type: none;\">\r\n<ul style=\"list-style-type: square;\">\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 102%; font-weight: bold;\"><strong><span style=\"font-size: 14pt;\">Notre feuille de route de production intègre les Bonnes Pratiques de Fabrication (BPF), </span></strong></li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 102%; font-weight: bold;\"><strong><span style=\"font-size: 14pt;\">des systèmes de laboratoire validés, des contrôles de traçabilité, et des protocoles de documentation réglementaire requis pour les marchés d\'exportation régionaux et internationaux des MTCAs, </span></strong></li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 102%; font-weight: bold;\"><strong><span style=\"font-size: 14pt;\">des Nutraceutiques/Compléments Alimentaires, des Phytomédicines et Phytopharmaceutiques, des aliments santé fortifiés clean-label et des boissons aux fruits.</span></strong></li>\r\n</ul>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 102%; margin: 0cm 0cm .2pt -.25pt;\" align=\"left\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 12pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 80px; text-align: left;\"><span style=\"font-size: 18pt;\"><strong><span style=\"color: rgb(45, 194, 107);\">NUFOTEC-PHYTOMED INDUSTRIES est soumise aux autorisations réglementaires suivantes :</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 80px; text-align: left;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Demande d\'exploitation & Enregistrement &ndash; PACRA</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Licence d\'Investissement - ZDA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 1.9pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Certificat d\'Étude d\'Impact Environnemental (EIE) - ZEMA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Certificat de Rapport EPB de Sélection - ZEMA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Licence de Gestion des Déchets - ZEMA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Certificat d\'Approbation de Site - ZMRA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 1.9pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Enregistrement de Produit - ZMRA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Inspection BPF - ZAMRA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Licence de Fabrication - ZAMRA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 1.9pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Permis d\'Investisseur - IMMIGRATION</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Test de Produit & Demande - ZABS</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Inspection d\'Usine - ZABS</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-s