INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(211, 18, 'hero', 'Partenariats stratégiques', 'Partenariats stratégiques', 'Strategic partnerships', 'Ushirikiano wa kimkakati', 'Partenaires financiers, techniques et scientifiques', 'Partenaires financiers, techniques et scientifiques', 'Financial, technical and scientific partners', 'Washirika wa kifedha, kiufundi na kisayansi', '', '', NULL, NULL, '/attachments/Sections/2026030300030469a60918e5854.jpg', 0, '', NULL, NULL, NULL, '', 0, '2026-03-03 00:03:04', '', NULL, '2026-03-24 18:29:11', NULL, 1),
(212, 18, 'liste_card', '', '', 'Financial, technical and scientific partners', 'Washirika wa kifedha, kiufundi na kisayansi', '', '', 'NUFOTEC-PHYTOMED INDUSTRIES collaborates with a carefully structured network of domestic, regional and international partners. These partnerships integrate scientific research, clinical validation, manufacturing expertise, regulatory advice and financial support to ensure that all natural medicines we produce are safe, standardized and globally credible.', 'NUFOTEC-PHYTOMED INDUSTRIES inashirikiana na mtandao uliopangwa kwa uangalifu wa washirika wa ndani, kikanda na kimataifa. Ushirikiano huu unajumuisha utafiti wa kisayansi, uthibitisho wa kimatibabu, utaalamu wa utengenezaji, ushauri wa udhibiti na usaidizi wa kifedha ili kuhakikisha kuwa dawa zote za asili tunazozalisha ni salama, sanifu na zinazoaminika kimataifa.', '<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm 20.75pt 0cm;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span>L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux. Ces partenariats intègrent la recherche scientifique, la validation clinique, l\'expertise en fabrication, les conseils réglementaires et le soutien financier pour garantir que tous les médicaments naturels que nous produisons sont sûrs, standardisés et crédibles à l\'échelle mondiale.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">&nbsp;</p>\r\n<p>1.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Recherche et validation scientifique</p>\r\n<p>Objectif : Valider les composés végétaux pour les maladies chroniques, notamment le cancer, le diabète et les maladies cardiovasculaires.</p>\r\n<p>Domestique : Université de Zambie – recherche préclinique, identification de biomarqueurs et études translationnelles.</p>\r\n<p>Régional : Université de Cape Town – études pharmacologiques et modélisation des maladies chroniques. International : Harvard Medical School, Université d\'Oxford, Karolinska Institutet – validation de mécanismes, recherche translationnelle et développement conjoint de propriété intellectuelle.</p>\r\n<p>&nbsp;</p>\r\n<p>2.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Essais cliniques et réseaux de santé</p>\r\n<p>Objectif : Mener des études sur l\'homme pour démontrer la sécurité et l\'efficacité.</p>\r\n<p>Domestique : Hôpitaux de Lusaka et cliniques MNT – recrutement de patients et suivi clinique.</p>\r\n<p>Régional : Hôpitaux de référence régionaux – coordination et gestion des études cliniques. International : MD Anderson Cancer Center, Mayo Clinic – collaboration sur les essais en oncologie et métabolisme, analyse statistique et conformité GCP.</p>\r\n<p>&nbsp;</p>\r\n<p>3.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Autorisation réglementaire et de mise sur le marché</p>\r\n<p>Objectif : Assurer la conformité aux normes nationales et internationales.</p>\r\n<p>Domestique : Zambia Medicines Regulatory Authority – enregistrement des produits et conseils en pharmacovigilance.</p>\r\n<p>Régional : Autorités réglementaires du COMESA – alignement régional et soutien à la conformité. International : Organisation mondiale de la santé – conseils sur l\'intégration de la médecine traditionnelle et les cadres mondiaux des MNT.</p>\r\n<p>&nbsp;</p>\r\n<p>4.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Fabrication et assurance qualité</p>\r\n<p>Objectif : Production à l\'échelle industrielle selon les normes BPF internationalement reconnues. Domestique : Consultants locaux en BPF – audits d\'installations, validation des processus et gestion de la qualité.</p>\r\n<p>Régional : Sociétés de certification régionales – standardisation des lots et assurance qualité. International : SGS, Bureau Veritas, TÜV Rheinland – certification BPF, validation des processus et conformité à l\'exportation.</p>\r\n<p>&nbsp;</p>\r\n<p>5.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Tests de sécurité et précliniques</p>\r\n<p>Objectif : Confirmer la sécurité de qualité réglementaire des produits avant les essais sur l\'homme.</p>\r\n<p>Domestique : Laboratoires précliniques locaux – criblage initial de toxicité et de sécurité.</p>\r\n<p>Régional : Laboratoires BPL régionaux – toxicité organique et études d\'exposition chronique.</p>\r\n<p>International : Charles River Laboratories, Evotec – toxicologie conforme aux BPL, pharmacocinétique et études habilitantes pour les IND.</p>\r\n<p>&nbsp;</p>\r\n<p>6.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Partenaires financiers et de développement</p>\r\n<p>Objectif : Fournir un financement, des conseils ESG et une mesure d\'impact.</p>\r\n<p>Domestique : Banque de Zambie, IFD locales – financement de démarrage et conseil ESG.</p>\r\n<p>Régional : Banque africaine de développement – mobilisation de capitaux, cadres ESG et financement mixte.</p>\r\n<p>International : International Finance Corporation, Fondation Bill &amp; Melinda Gates – financement à impact, structuration de financements mixtes et alignement avec les donateurs mondiaux.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Conclusion</p>\r\n<p><span style=\"font-size: 14.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Grâce à ce réseau intégré de partenaires financiers, techniques et scientifiques, NUFOTEC-PHYTOMED garantit que chaque étape de son développement phytopharmaceutique est scientifiquement validée, cliniquement prouvée et fabriquée selon les normes de qualité internationales. Ces collaborations nous permettent de fournir des médicaments naturels sûrs, standardisés et crédibles à l\'échelle mondiale qui ciblent les maladies chroniques à forte charge tout en attirant les investissements, en permettant l\'accès au marché et en générant un impact social et sanitaire mesurable.</span></p>', '<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm 20.75pt 0cm;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span>L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux. Ces partenariats intègrent la recherche scientifique, la validation clinique, l\'expertise en fabrication, les conseils réglementaires et le soutien financier pour garantir que tous les médicaments naturels que nous produisons sont sûrs, standardisés et crédibles à l\'échelle mondiale.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">&nbsp;</p>\r\n<p>1.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Recherche et validation scientifique</p>\r\n<p>Objectif : Valider les composés végétaux pour les maladies chroniques, notamment le cancer, le diabète et les maladies cardiovasculaires.</p>\r\n<p>Domestique : Université de Zambie – recherche préclinique, identification de biomarqueurs et études translationnelles.</p>\r\n<p>Régional : Université de Cape Town – études pharmacologiques et modélisation des maladies chroniques. International : Harvard Medical School, Université d\'Oxford, Karolinska Institutet – validation de mécanismes, recherche translationnelle et développement conjoint de propriété intellectuelle.</p>\r\n<p>&nbsp;</p>\r\n<p>2.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Essais cliniques et réseaux de santé</p>\r\n<p>Objectif : Mener des études sur l\'homme pour démontrer la sécurité et l\'efficacité.</p>\r\n<p>Domestique : Hôpitaux de Lusaka et cliniques MNT – recrutement de patients et suivi clinique.</p>\r\n<p>Régional : Hôpitaux de référence régionaux – coordination et gestion des études cliniques. International : MD Anderson Cancer Center, Mayo Clinic – collaboration sur les essais en oncologie et métabolisme, analyse statistique et conformité GCP.</p>\r\n<p>&nbsp;</p>\r\n<p>3.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Autorisation réglementaire et de mise sur le marché</p>\r\n<p>Objectif : Assurer la conformité aux normes nationales et internationales.</p>\r\n<p>Domestique : Zambia Medicines Regulatory Authority – enregistrement des produits et conseils en pharmacovigilance.</p>\r\n<p>Régional : Autorités réglementaires du COMESA – alignement régional et soutien à la conformité. International : Organisation mondiale de la santé – conseils sur l\'intégration de la médecine traditionnelle et les cadres mondiaux des MNT.</p>\r\n<p>&nbsp;</p>\r\n<p>4.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Fabrication et assurance qualité</p>\r\n<p>Objectif : Production à l\'échelle industrielle selon les normes BPF internationalement reconnues. Domestique : Consultants locaux en BPF – audits d\'installations, validation des processus et gestion de la qualité.</p>\r\n<p>Régional : Sociétés de certification régionales – standardisation des lots et assurance qualité. International : SGS, Bureau Veritas, TÜV Rheinland – certification BPF, validation des processus et conformité à l\'exportation.</p>\r\n<p>&nbsp;</p>\r\n<p>5.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Tests de sécurité et précliniques</p>\r\n<p>Objectif : Confirmer la sécurité de qualité réglementaire des produits avant les essais sur l\'homme.</p>\r\n<p>Domestique : Laboratoires précliniques locaux – criblage initial de toxicité et de sécurité.</p>\r\n<p>Régional : Laboratoires BPL régionaux – toxicité organique et études d\'exposition chronique.</p>\r\n<p>International : Charles River Laboratories, Evotec – toxicologie conforme aux BPL, pharmacocinétique et études habilitantes pour les IND.</p>\r\n<p>&nbsp;</p>\r\n<p>6.<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Partenaires financiers et de développement</p>\r\n<p>Objectif : Fournir un financement, des conseils ESG et une mesure d\'impact.</p>\r\n<p>Domestique : Banque de Zambie, IFD locales – financement de démarrage et conseil ESG.</p>\r\n<p>Régional : Banque africaine de développement – mobilisation de capitaux, cadres ESG et financement mixte.</p>\r\n<p>International : International Finance Corporation, Fondation Bill &amp; Melinda Gates – financement à impact, structuration de financements mixtes et alignement avec les donateurs mondiaux.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Conclusion</p>\r\n<p><span style=\"font-size: 14.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Grâce à ce réseau intégré de partenaires financiers, techniques et scientifiques, NUFOTEC-PHYTOMED garantit que chaque étape de son développement phytopharmaceutique est scientifiquement validée, cliniquement prouvée et fabriquée selon les normes de qualité internationales. Ces collaborations nous permettent de fournir des médicaments naturels sûrs, standardisés et crédibles à l\'échelle mondiale qui ciblent les maladies chroniques à forte charge tout en attirant les investissements, en permettant l\'accès au marché et en générant un impact social et sanitaire mesurable.</span></p>', NULL, NULL, NULL, 0, '', NULL, NULL, NULL, '', 0, '2026-03-03 00:09:04', '', NULL, '2026-03-03 00:39:10', '2026-03-03 00:39:10', 1),
(213, 18, 'grille', 'Partenaires financiers, techniques et scientifiques', 'Partenaires financiers, techniques et scientifiques', NULL, NULL, 'L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux. Ces partenariats intègrent la recherche scientifique, la validation clinique, l\'expertise en fabrication, les conseils réglementaires et le soutien financier afin de garantir que tous les médicaments naturels que nous produisons sont sûrs, standardisés et crédibles à l\'échelle mondiale.', 'L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux. Ces partenariats intègrent la recherche scientifique, la validation clinique, l\'expertise en fabrication, les conseils réglementaires et le soutien financier afin de garantir que tous les médicaments naturels que nous produisons sont sûrs, standardisés et crédibles à l\'échelle mondiale.', NULL, NULL, '<div class=\"partner-category\">\r\n    <h3>1. Recherche et validation scientifique</h3>\r\n    <p><strong>Objectif:</strong> Valider les composés végétaux pour les maladies chroniques, notamment le cancer, le diabète et les maladies cardiovasculaires.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Université de Zambie – recherche préclinique, identification de biomarqueurs et études translationnelles.</li>\r\n        <li><strong>Régional:</strong> Université de Cape Town – études pharmacologiques et modélisation des maladies chroniques.</li>\r\n        <li><strong>International:</strong> Harvard Medical School, Université d\'Oxford, Karolinska Institutet – validation de mécanismes, recherche translationnelle et développement conjoint de propriété intellectuelle.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>2. Essais cliniques et réseaux de santé</h3>\r\n    <p><strong>Objectif:</strong> Mener des études sur l\'homme pour démontrer la sécurité et l\'efficacité.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Hôpitaux de Lusaka et cliniques MNT – recrutement de patients et suivi clinique.</li>\r\n        <li><strong>Régional:</strong> Hôpitaux de référence régionaux – coordination et gestion des études cliniques.</li>\r\n        <li><strong>International:</strong> MD Anderson Cancer Center, Mayo Clinic – collaboration sur les essais en oncologie et métabolisme, analyse statistique et conformité GCP.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>3. Autorisation réglementaire et de mise sur le marché</h3>\r\n    <p><strong>Objectif:</strong> Assurer la conformité aux normes nationales et internationales.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Zambia Medicines Regulatory Authority – enregistrement des produits et conseils en pharmacovigilance.</li>\r\n        <li><strong>Régional:</strong> Autorités réglementaires du COMESA – alignement régional et soutien à la conformité.</li>\r\n        <li><strong>International:</strong> Organisation mondiale de la santé – conseils sur l\'intégration de la médecine traditionnelle et les cadres mondiaux des MNT.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>4. Fabrication et assurance qualité</h3>\r\n    <p><strong>Objectif:</strong> Production à l\'échelle industrielle selon les normes BPF internationalement reconnues.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Consultants locaux en BPF – audits d\'installations, validation des processus et gestion de la qualité.</li>\r\n        <li><strong>Régional:</strong> Sociétés de certification régionales – standardisation des lots et assurance qualité.</li>\r\n        <li><strong>International:</strong> SGS, Bureau Veritas, TÜV Rheinland – certification BPF, validation des processus et conformité à l\'exportation.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>5. Tests de sécurité et précliniques</h3>\r\n    <p><strong>Objectif:</strong> Confirmer la sécurité de qualité réglementaire des produits avant les essais sur l\'homme.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Laboratoires précliniques locaux – criblage initial de toxicité et de sécurité.</li>\r\n        <li><strong>Régional:</strong> Laboratoires BPL régionaux – toxicité organique et études d\'exposition chronique.</li>\r\n        <li><strong>International:</strong> Charles River Laboratories, Evotec – toxicologie conforme aux BPL, pharmacocinétique et études habilitantes pour les IND.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>6. Partenaires financiers et de développement</h3>\r\n    <p><strong>Objectif:</strong> Fournir un financement, des conseils ESG et une mesure d\'impact.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Banque de Zambie, IFD locales – financement de démarrage et conseil ESG.</li>\r\n        <li><strong>Régional:</strong> Banque africaine de développement – mobilisation de capitaux, cadres ESG et financement mixte.</li>\r\n        <li><strong>International:</strong> International Finance Corporation, Fondation Bill & Melinda Gates – financement à impact, structuration de financements mixtes et alignement avec les donateurs mondiaux.</li>\r\n    </ul>\r\n</div>\r\n<p class=\"conclusion\"><strong>Conclusion</strong><br>Grâce à ce réseau intégré de partenaires financiers, techniques et scientifiques, NUFOTEC-PHYTOMED garantit que chaque étape de son développement phytopharmaceutique est scientifiquement validée, cliniquement prouvée et fabriquée selon les normes de qualité internationales. Ces collaborations nous permettent de fournir des médicaments naturels sûrs, standardisés et crédibles à l\'échelle mondiale qui ciblent les maladies chroniques à forte charge tout en attirant les investissements, en permettant l\'accès au marché et en générant un impact social et sanitaire mesurable.</p>', '<div class=\"partner-category\">\r\n    <h3>1. Recherche et validation scientifique</h3>\r\n    <p><strong>Objectif:</strong> Valider les composés végétaux pour les maladies chroniques, notamment le cancer, le diabète et les maladies cardiovasculaires.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Université de Zambie – recherche préclinique, identification de biomarqueurs et études translationnelles.</li>\r\n        <li><strong>Régional:</strong> Université de Cape Town – études pharmacologiques et modélisation des maladies chroniques.</li>\r\n        <li><strong>International:</strong> Harvard Medical School, Université d\'Oxford, Karolinska Institutet – validation de mécanismes, recherche translationnelle et développement conjoint de propriété intellectuelle.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>2. Essais cliniques et réseaux de santé</h3>\r\n    <p><strong>Objectif:</strong> Mener des études sur l\'homme pour démontrer la sécurité et l\'efficacité.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Hôpitaux de Lusaka et cliniques MNT – recrutement de patients et suivi clinique.</li>\r\n        <li><strong>Régional:</strong> Hôpitaux de référence régionaux – coordination et gestion des études cliniques.</li>\r\n        <li><strong>International:</strong> MD Anderson Cancer Center, Mayo Clinic – collaboration sur les essais en oncologie et métabolisme, analyse statistique et conformité GCP.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>3. Autorisation réglementaire et de mise sur le marché</h3>\r\n    <p><strong>Objectif:</strong> Assurer la conformité aux normes nationales et internationales.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Zambia Medicines Regulatory Authority – enregistrement des produits et conseils en pharmacovigilance.</li>\r\n        <li><strong>Régional:</strong> Autorités réglementaires du COMESA – alignement régional et soutien à la conformité.</li>\r\n        <li><strong>International:</strong> Organisation mondiale de la santé – conseils sur l\'intégration de la médecine traditionnelle et les cadres mondiaux des MNT.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>4. Fabrication et assurance qualité</h3>\r\n    <p><strong>Objectif:</strong> Production à l\'échelle industrielle selon les normes BPF internationalement reconnues.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Consultants locaux en BPF – audits d\'installations, validation des processus et gestion de la qualité.</li>\r\n        <li><strong>Régional:</strong> Sociétés de certification régionales – standardisation des lots et assurance qualité.</li>\r\n        <li><strong>International:</strong> SGS, Bureau Veritas, TÜV Rheinland – certification BPF, validation des processus et conformité à l\'exportation.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>5. Tests de sécurité et précliniques</h3>\r\n    <p><strong>Objectif:</strong> Confirmer la sécurité de qualité réglementaire des produits avant les essais sur l\'homme.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Laboratoires précliniques locaux – criblage initial de toxicité et de sécurité.</li>\r\n        <li><strong>Régional:</strong> Laboratoires BPL régionaux – toxicité organique et études d\'exposition chronique.</li>\r\n        <li><strong>International:</strong> Charles River Laboratories, Evotec – toxicologie conforme aux BPL, pharmacocinétique et études habilitantes pour les IND.</li>\r\n    </ul>\r\n</div>\r\n<div class=\"partner-category\">\r\n    <h3>6. Partenaires financiers et de développement</h3>\r\n    <p><strong>Objectif:</strong> Fournir un financement, des conseils ESG et une mesure d\'impact.</p>\r\n    <ul>\r\n        <li><strong>Domestique:</strong> Banque de Zambie, IFD locales – financement de démarrage et conseil ESG.</li>\r\n        <li><strong>Régional:</strong> Banque africaine de développement – mobilisation de capitaux, cadres ESG et financement mixte.</li>\r\n        <li><strong>International:</strong> International Finance Corporation, Fondation Bill & Melinda Gates – financement à impact, structuration de financements mixtes et alignement avec les donateurs mondiaux.</li>\r\n    </ul>\r\n</div>\r\n<p class=\"conclusion\"><strong>Conclusion</strong><br>Grâce à ce réseau intégré de partenaires financiers, techniques et scientifiques, NUFOTEC-PHYTOMED garantit que chaque étape de son développement phytopharmaceutique est scientifiquement validée, cliniquement prouvée et fabriquée selon les normes de qualité internationales. Ces collaborations nous permettent de fournir des médicaments naturels sûrs, standardisés et crédibles à l\'échelle mondiale qui ciblent les maladies chroniques à forte charge tout en attirant les investissements, en permettant l\'accès au marché et en générant un impact social et sanitaire mesurable.</p>', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 2, '2026-03-03 00:17:14', 'partners-grid', '{\"layout\": \"grid\", \"columns\": 2, \"card_style\": \"bordered\", \"gap\": \"lg\", \"padding\": \"md\", \"bg_color\": \"#f8f9fa\", \"title_size\": \"h3\"}', '2026-03-03 00:39:01', '2026-03-03 00:39:01', 1),
(214, 18, 'liste', 'Partenaires financiers, techniques et scientifiques', 'Partenaires financiers, techniques et scientifiques', NULL, NULL, 'L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux.', 'L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux.', NULL, NULL, '<ul>\r\n    <li><strong>1. Recherche et validation scientifique</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Valider les composés végétaux.</li>\r\n            <li><strong>Domestique:</strong> Université de Zambie (recherche préclinique).</li>\r\n            <li><strong>Régional:</strong> Université du Cap (études pharmacologiques).</li>\r\n            <li><strong>International:</strong> Harvard, Oxford, Karolinska (validation de mécanismes).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>2. Essais cliniques et réseaux de santé</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Mener des études sur l\'homme.</li>\r\n            <li><strong>Domestique:</strong> Hôpitaux de Lusaka (recrutement de patients).</li>\r\n            <li><strong>Régional:</strong> Hôpitaux régionaux de référence (coordination).</li>\r\n            <li><strong>International:</strong> MD Anderson, Mayo Clinic (collaboration sur les essais).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>3. Autorisation réglementaire et de mise sur le marché</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Assurer la conformité.</li>\r\n            <li><strong>Domestique:</strong> ZAMRA (enregistrement des produits).</li>\r\n            <li><strong>Régional:</strong> Autorités du COMESA (alignement).</li>\r\n            <li><strong>International:</strong> Organisation mondiale de la santé (conseils).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>4. Fabrication et assurance qualité</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Production aux normes BPF.</li>\r\n            <li><strong>Domestique:</strong> Consultants locaux en BPF (audits).</li>\r\n            <li><strong>Régional:</strong> Sociétés de certification régionales (assurance qualité).</li>\r\n            <li><strong>International:</strong> SGS, Bureau Veritas, TÜV Rheinland (certification BPF).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>5. Tests de sécurité et précliniques</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Confirmer la sécurité préclinique.</li>\r\n            <li><strong>Domestique:</strong> Laboratoires précliniques locaux (criblage de toxicité).</li>\r\n            <li><strong>Régional:</strong> Laboratoires BPL régionaux (études de toxicité).</li>\r\n            <li><strong>International:</strong> Charles River Laboratories, Evotec (études habilitantes).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>6. Partenaires financiers et de développement</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Fournir du financement et des conseils ESG.</li>\r\n            <li><strong>Domestique:</strong> Banque de Zambie, IFD locales (financement de démarrage).</li>\r\n            <li><strong>Régional:</strong> Banque africaine de développement (mobilisation de capitaux).</li>\r\n            <li><strong>International:</strong> IFC, Fondation Gates (financement à impact).</li>\r\n        </ul>\r\n    </li>\r\n</ul>\r\n<p><strong>Conclusion:</strong> Grâce à ce réseau intégré, NUFOTEC-PHYTOMED s\'assure que le développement de ses produits est scientifiquement validé, cliniquement prouvé et fabriqué selon les normes internationales, nous permettant de fournir des médicaments naturels sûrs et crédibles à l\'échelle mondiale.</p>', '<ul>\r\n    <li><strong>1. Recherche et validation scientifique</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Valider les composés végétaux.</li>\r\n            <li><strong>Domestique:</strong> Université de Zambie (recherche préclinique).</li>\r\n            <li><strong>Régional:</strong> Université du Cap (études pharmacologiques).</li>\r\n            <li><strong>International:</strong> Harvard, Oxford, Karolinska (validation de mécanismes).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>2. Essais cliniques et réseaux de santé</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Mener des études sur l\'homme.</li>\r\n            <li><strong>Domestique:</strong> Hôpitaux de Lusaka (recrutement de patients).</li>\r\n            <li><strong>Régional:</strong> Hôpitaux régionaux de référence (coordination).</li>\r\n            <li><strong>International:</strong> MD Anderson, Mayo Clinic (collaboration sur les essais).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>3. Autorisation réglementaire et de mise sur le marché</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Assurer la conformité.</li>\r\n            <li><strong>Domestique:</strong> ZAMRA (enregistrement des produits).</li>\r\n            <li><strong>Régional:</strong> Autorités du COMESA (alignement).</li>\r\n            <li><strong>International:</strong> Organisation mondiale de la santé (conseils).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>4. Fabrication et assurance qualité</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Production aux normes BPF.</li>\r\n            <li><strong>Domestique:</strong> Consultants locaux en BPF (audits).</li>\r\n            <li><strong>Régional:</strong> Sociétés de certification régionales (assurance qualité).</li>\r\n            <li><strong>International:</strong> SGS, Bureau Veritas, TÜV Rheinland (certification BPF).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>5. Tests de sécurité et précliniques</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Confirmer la sécurité préclinique.</li>\r\n            <li><strong>Domestique:</strong> Laboratoires précliniques locaux (criblage de toxicité).</li>\r\n            <li><strong>Régional:</strong> Laboratoires BPL régionaux (études de toxicité).</li>\r\n            <li><strong>International:</strong> Charles River Laboratories, Evotec (études habilitantes).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>6. Partenaires financiers et de développement</strong>\r\n        <ul>\r\n            <li><em>Objectif:</em> Fournir du financement et des conseils ESG.</li>\r\n            <li><strong>Domestique:</strong> Banque de Zambie, IFD locales (financement de démarrage).</li>\r\n            <li><strong>Régional:</strong> Banque africaine de développement (mobilisation de capitaux).</li>\r\n            <li><strong>International:</strong> IFC, Fondation Gates (financement à impact).</li>\r\n        </ul>\r\n    </li>\r\n</ul>\r\n<p><strong>Conclusion:</strong> Grâce à ce réseau intégré, NUFOTEC-PHYTOMED s\'assure que le développement de ses produits est scientifiquement validé, cliniquement prouvé et fabriqué selon les normes internationales, nous permettant de fournir des médicaments naturels sûrs et crédibles à l\'échelle mondiale.</p>', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 2, '2026-03-03 00:20:09', NULL, NULL, '2026-03-03 00:38:50', '2026-03-03 00:38:49', 1),
(215, 18, 'liste_card', 'Partenaires financiers, techniques et scientifiques', 'Partenaires financiers, techniques et scientifiques', NULL, NULL, 'L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux. Ces partenariats intègrent la recherche scientifique, la validation clinique, l\'expertise en fabrication, les conseils réglementaires et le soutien financier afin de garantir que tous les médicaments naturels que nous produisons sont sûrs, standardisés et crédibles à l\'échelle mondiale.', 'L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux. Ces partenariats intègrent la recherche scientifique, la validation clinique, l\'expertise en fabrication, les conseils réglementaires et le soutien financier afin de garantir que tous les médicaments naturels que nous produisons sont sûrs, standardisés et crédibles à l\'échelle mondiale.', NULL, NULL, '<div class=\"partner-category\">\r\n<ul>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Recherche et validation scientifique:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Valider les composés végétaux pour les maladies chroniques, notamment le cancer, le diabète et les maladies cardiovasculaires.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Université de Zambie &ndash; recherche préclinique, identification de biomarqueurs et études translationnelles.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Université de Cape Town &ndash; études pharmacologiques et modélisation des maladies chroniques. International: Harvard Medical School, Université d\'Oxford, Karolinska Institutet &ndash; validation de mécanismes, recherche translationnelle et développement conjoint de propriété intellectuelle.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Essais cliniques et réseaux de santé:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Mener des études sur l\'homme pour démontrer la sécurité et l\'efficacité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Hôpitaux de Lusaka et cliniques MNT &ndash; recrutement de patients et suivi clinique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Hôpitaux de référence régionaux &ndash; coordination et gestion des études cliniques. International: MD Anderson Cancer Center, Mayo Clinic &ndash; collaboration sur les essais en oncologie et métabolisme, analyse statistique et conformité GCP.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Autorisation réglementaire et de mise sur le marché:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Assurer la conformité aux normes nationales et internationales.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Zambia Medicines Regulatory Authority &ndash; enregistrement des produits et conseils en pharmacovigilance.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Autorités réglementaires du COMESA &ndash; alignement régional et soutien à la conformité. International: Organisation mondiale de la santé &ndash; conseils sur l\'intégration de la médecine traditionnelle et les cadres mondiaux des MNT.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Fabrication et assurance qualité:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Production à l\'échelle industrielle selon les normes BPF internationalement reconnues. Domestique: Consultants locaux en BPF &ndash; audits d\'installations, validation des processus et gestion de la qualité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Sociétés de certification régionales &ndash; standardisation des lots et assurance qualité. International: SGS, Bureau Veritas, TÜV Rheinland &ndash; certification BPF, validation des processus et conformité à l\'exportation.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Tests de sécurité et précliniques:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Confirmer la sécurité de qualité réglementaire des produits avant les essais sur l\'homme.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Laboratoires précliniques locaux &ndash; criblage initial de toxicité et de sécurité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Laboratoires BPL régionaux &ndash; toxicité organique et études d\'exposition chronique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">International: Charles River Laboratories, Evotec &ndash; toxicologie conforme aux BPL, pharmacocinétique et études habilitantes pour les IND.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Partenaires financiers et de développement:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Fournir un financement, des conseils ESG et une mesure d\'impact.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Banque de Zambie, IFD locales &ndash; financement de démarrage et conseil ESG.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Banque africaine de développement &ndash; mobilisation de capitaux, cadres ESG et financement mixte.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">International: International Finance Corporation, Fondation Bill &amp; Melinda Gates &ndash; financement à impact, structuration de financements mixtes et alignement avec les donateurs mondiaux.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Conclusion</p>\r\n</li>\r\n</ul>\r\n</div>\r\n<p class=\"conclusion\">&nbsp;</p>', '<div class=\"partner-category\">\r\n<ul>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Recherche et validation scientifique:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Valider les composés végétaux pour les maladies chroniques, notamment le cancer, le diabète et les maladies cardiovasculaires.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Université de Zambie &ndash; recherche préclinique, identification de biomarqueurs et études translationnelles.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Université de Cape Town &ndash; études pharmacologiques et modélisation des maladies chroniques. International: Harvard Medical School, Université d\'Oxford, Karolinska Institutet &ndash; validation de mécanismes, recherche translationnelle et développement conjoint de propriété intellectuelle.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Essais cliniques et réseaux de santé:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Mener des études sur l\'homme pour démontrer la sécurité et l\'efficacité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Hôpitaux de Lusaka et cliniques MNT &ndash; recrutement de patients et suivi clinique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Hôpitaux de référence régionaux &ndash; coordination et gestion des études cliniques. International: MD Anderson Cancer Center, Mayo Clinic &ndash; collaboration sur les essais en oncologie et métabolisme, analyse statistique et conformité GCP.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Autorisation réglementaire et de mise sur le marché:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Assurer la conformité aux normes nationales et internationales.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Zambia Medicines Regulatory Authority &ndash; enregistrement des produits et conseils en pharmacovigilance.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Autorités réglementaires du COMESA &ndash; alignement régional et soutien à la conformité. International: Organisation mondiale de la santé &ndash; conseils sur l\'intégration de la médecine traditionnelle et les cadres mondiaux des MNT.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Fabrication et assurance qualité:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Production à l\'échelle industrielle selon les normes BPF internationalement reconnues. Domestique: Consultants locaux en BPF &ndash; audits d\'installations, validation des processus et gestion de la qualité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Sociétés de certification régionales &ndash; standardisation des lots et assurance qualité. International: SGS, Bureau Veritas, TÜV Rheinland &ndash; certification BPF, validation des processus et conformité à l\'exportation.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Tests de sécurité et précliniques:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Confirmer la sécurité de qualité réglementaire des produits avant les essais sur l\'homme.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Laboratoires précliniques locaux &ndash; criblage initial de toxicité et de sécurité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Laboratoires BPL régionaux &ndash; toxicité organique et études d\'exposition chronique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">International: Charles River Laboratories, Evotec &ndash; toxicologie conforme aux BPL, pharmacocinétique et études habilitantes pour les IND.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Partenaires financiers et de développement:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Fournir un financement, des conseils ESG et une mesure d\'impact.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Domestique: Banque de Zambie, IFD locales &ndash; financement de démarrage et conseil ESG.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Banque africaine de développement &ndash; mobilisation de capitaux, cadres ESG et financement mixte.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">International: International Finance Corporation, Fondation Bill &amp; Melinda Gates &ndash; financement à impact, structuration de financements mixtes et alignement avec les donateurs mondiaux.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Conclusion</p>\r\n</li>\r\n</ul>\r\n</div>\r\n<p class=\"conclusion\">&nbsp;</p>', NULL, NULL, NULL, 0, '', NULL, NULL, NULL, '', 2, '2026-03-03 00:20:41', 'partners-grid', '{\"layout\": \"grid\", \"columns\": 2, \"card_style\": \"bordered\", \"gap\": \"lg\", \"padding\": \"md\", \"bg_color\": \"#f8f9fa\", \"title_size\": \"h4\"}', '2026-03-03 00:49:58', '2026-03-03 00:49:57', 1);
INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(216, 18, 'texte', 'Partenaires financiers, techniques et scientifiques', 'Partenaires financiers, techniques et scientifiques', 'Financial, technical and scientific partners', 'Washirika wa kifedha, kiufundi na kisayansi', 'L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux. Ces partenariats intègrent la recherche scientifique, la validation clinique, l\'expertise en fabrication, les conseils réglementaires et le soutien financier afin de garantir que tous les médicaments naturels que nous produisons sont sûrs, standardisés et crédibles à l\'échelle mondiale.', 'L\'INSTALLATION NUFOTEC-PHYTOMED INDUSTRIES collabore avec un réseau soigneusement structuré de partenaires domestiques, régionaux et internationaux. Ces partenariats intègrent la recherche scientifique, la validation clinique, l\'expertise en fabrication, les conseils réglementaires et le soutien financier afin de garantir que tous les médicaments naturels que nous produisons sont sûrs, standardisés et crédibles à l\'échelle mondiale.', 'NUFOTEC-PHYTOMED INDUSTRIES collaborates with a carefully structured network of domestic, regional and international partners. These partnerships integrate scientific research, clinical validation, manufacturing expertise, regulatory advice and financial support to ensure that all natural medicines we produce are safe, standardized and globally credible.', 'NUFOTEC-PHYTOMED INDUSTRIES inashirikiana na mtandao uliopangwa kwa uangalifu wa washirika wa ndani, kikanda na kimataifa. Ushirikiano huu unajumuisha utafiti wa kisayansi, uthibitisho wa kimatibabu, utaalamu wa utengenezaji, ushauri wa udhibiti na usaidizi wa kifedha ili kuhakikisha kuwa dawa zote za asili tunazozalisha ni salama, sanifu na zinazoaminika kimataifa.', '<div class=\"partner-category\">\r\n<ul>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Recherche et validation scientifique:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif: </strong>Valider les composés végétaux pour les maladies chroniques, notamment le cancer, le diabète et les maladies cardiovasculaires.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique: </strong>Université de Zambie &ndash; recherche préclinique, identification de biomarqueurs et études translationnelles.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Régional:</strong> Université de Cape Town &ndash; études pharmacologiques et modélisation des maladies chroniques. International: Harvard Medical School, Université d\'Oxford, Karolinska Institutet &ndash; validation de mécanismes, recherche translationnelle et développement conjoint de propriété intellectuelle.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Essais cliniques et réseaux de santé:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif:</strong> Mener des études sur l\'homme pour démontrer la sécurité et l\'efficacité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique:</strong> Hôpitaux de Lusaka et cliniques MNT &ndash; recrutement de patients et suivi clinique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Hôpitaux de référence régionaux &ndash; coordination et gestion des études cliniques. International: MD Anderson Cancer Center, Mayo Clinic &ndash; collaboration sur les essais en oncologie et métabolisme, analyse statistique et conformité GCP.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Autorisation réglementaire et de mise sur le marché:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif:</strong> Assurer la conformité aux normes nationales et internationales.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique: </strong>Zambia Medicines Regulatory Authority &ndash; enregistrement des produits et conseils en pharmacovigilance.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Régional:</strong> Autorités réglementaires du COMESA &ndash; alignement régional et soutien à la conformité. International: Organisation mondiale de la santé &ndash; conseils sur l\'intégration de la médecine traditionnelle et les cadres mondiaux des MNT.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Fabrication et assurance qualité:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Production à l\'échelle industrielle selon les normes BPF internationalement reconnues. Domestique: Consultants locaux en BPF &ndash; audits d\'installations, validation des processus et gestion de la qualité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Sociétés de certification régionales &ndash; standardisation des lots et assurance qualité. International: SGS, Bureau Veritas, TÜV Rheinland &ndash; certification BPF, validation des processus et conformité à l\'exportation.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Tests de sécurité et précliniques:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif:</strong> Confirmer la sécurité de qualité réglementaire des produits avant les essais sur l\'homme.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique:</strong> Laboratoires précliniques locaux &ndash; criblage initial de toxicité et de sécurité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Régional:</strong> Laboratoires BPL régionaux &ndash; toxicité organique et études d\'exposition chronique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">International: Charles River Laboratories, Evotec &ndash; toxicologie conforme aux BPL, pharmacocinétique et études habilitantes pour les IND.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Partenaires financiers et de développement:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif:</strong> Fournir un financement, des conseils ESG et une mesure d\'impact.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique:</strong> Banque de Zambie, IFD locales &ndash; financement de démarrage et conseil ESG.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Régional:</strong> Banque africaine de développement &ndash; mobilisation de capitaux, cadres ESG et financement mixte.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">International: International Finance Corporation, Fondation Bill &amp; Melinda Gates &ndash; financement à impact, structuration de financements mixtes et alignement avec les donateurs mondiaux.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Conclusion</p>\r\n</li>\r\n</ul>\r\n</div>\r\n<p class=\"conclusion\">&nbsp;</p>', '<div class=\"partner-category\">\r\n<ul>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Recherche et validation scientifique:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif: </strong>Valider les composés végétaux pour les maladies chroniques, notamment le cancer, le diabète et les maladies cardiovasculaires.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique: </strong>Université de Zambie &ndash; recherche préclinique, identification de biomarqueurs et études translationnelles.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Régional:</strong> Université de Cape Town &ndash; études pharmacologiques et modélisation des maladies chroniques. International: Harvard Medical School, Université d\'Oxford, Karolinska Institutet &ndash; validation de mécanismes, recherche translationnelle et développement conjoint de propriété intellectuelle.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Essais cliniques et réseaux de santé:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif:</strong> Mener des études sur l\'homme pour démontrer la sécurité et l\'efficacité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique:</strong> Hôpitaux de Lusaka et cliniques MNT &ndash; recrutement de patients et suivi clinique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Hôpitaux de référence régionaux &ndash; coordination et gestion des études cliniques. International: MD Anderson Cancer Center, Mayo Clinic &ndash; collaboration sur les essais en oncologie et métabolisme, analyse statistique et conformité GCP.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Autorisation réglementaire et de mise sur le marché:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif:</strong> Assurer la conformité aux normes nationales et internationales.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique: </strong>Zambia Medicines Regulatory Authority &ndash; enregistrement des produits et conseils en pharmacovigilance.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Régional:</strong> Autorités réglementaires du COMESA &ndash; alignement régional et soutien à la conformité. International: Organisation mondiale de la santé &ndash; conseils sur l\'intégration de la médecine traditionnelle et les cadres mondiaux des MNT.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Fabrication et assurance qualité:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Objectif: Production à l\'échelle industrielle selon les normes BPF internationalement reconnues. Domestique: Consultants locaux en BPF &ndash; audits d\'installations, validation des processus et gestion de la qualité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Régional: Sociétés de certification régionales &ndash; standardisation des lots et assurance qualité. International: SGS, Bureau Veritas, TÜV Rheinland &ndash; certification BPF, validation des processus et conformité à l\'exportation.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Tests de sécurité et précliniques:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif:</strong> Confirmer la sécurité de qualité réglementaire des produits avant les essais sur l\'homme.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique:</strong> Laboratoires précliniques locaux &ndash; criblage initial de toxicité et de sécurité.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Régional:</strong> Laboratoires BPL régionaux &ndash; toxicité organique et études d\'exposition chronique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">International: Charles River Laboratories, Evotec &ndash; toxicologie conforme aux BPL, pharmacocinétique et études habilitantes pour les IND.</p>\r\n</li>\r\n<li style=\"font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 18pt;\"><strong>Partenaires financiers et de développement:</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Objectif:</strong> Fournir un financement, des conseils ESG et une mesure d\'impact.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Domestique:</strong> Banque de Zambie, IFD locales &ndash; financement de démarrage et conseil ESG.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong>Régional:</strong> Banque africaine de développement &ndash; mobilisation de capitaux, cadres ESG et financement mixte.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">International: International Finance Corporation, Fondation Bill &amp; Melinda Gates &ndash; financement à impact, structuration de financements mixtes et alignement avec les donateurs mondiaux.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\">Conclusion</p>\r\n</li>\r\n</ul>\r\n</div>\r\n<p class=\"conclusion\">&nbsp;</p>', NULL, NULL, NULL, 0, '', NULL,