INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(236, 12, 'texte', 'Plateforme de croissance digitale et d\'expansion commerciale', 'Plateforme de croissance digitale et d\'expansion commerciale', 'Digital growth and business expansion platform', 'Jukwaa la ukuaji wa kidijitali na upanuzi wa biashara', 'Croissance du marché pilotée par l\'IA, multicanal et communautaire', 'Croissance du marché pilotée par l\'IA, multicanal et communautaire', 'AI-driven, multi-channel, community-powered market growth', 'Ukuaji wa soko unaoendeshwa na AI, njia nyingi na jamii', '<h2 style=\"margin-left: -.25pt;\">1)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Aperçu stratégique</h2>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .8pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">La plateforme de croissance digitale et d\'expansion commerciale d\'NUFOTEC centralise tous les canaux de marketing digital stratégiques, y compris les groupes WhatsApp éducatifs existants et en constante expansion, Telegram, Facebook, Instagram, TikTok, YouTube, les e-mails et le site web, dans un système unique et coordonné utilisant HubSpot Marketing Hub. Intégrée à ChatGPT IA, cette plateforme automatise le contenu quotidien, les publicités et l\'engagement communautaire, garantissant une expansion du marché scalable, mesurable et professionnelle.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Avantage pour l\'investisseur : KPI transparents, analyses en temps réel et croissance prévisible sur les marchés domestiques, régionaux et internationaux.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<h2 style=\"margin-left: -.25pt;\">2)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Engagement communautaire et d\'experts</h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">235+ groupes WhatsApp, 211 500+ participants, en expansion quotidienne</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Partenaire clé : NUFOTEC BURUNDI (EAC)</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Contenu dirigé par des experts : Des nutritionnistes, diététiciens et professionnels de santé agréés fournissent des conseils quotidiens et des informations sur :</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Maladies aiguës : ex. toux, diarrhée, infections respiratoires</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Maladies chroniques : cancer, diabète, maladies cardiovasculaires, obésité, malnutrition infantile</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Nutrition préventive, remèdes maison et agriculture biologique</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Les communautés agissent comme des canaux actifs de marketing et d\'éducation, convertissant l\'engagement en adoption de produits et en développement économique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<h2 style=\"margin-left: -.25pt;\">3)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Services ChatGPT IA</h2>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .3pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Rôle :</strong> Pilote tout le contenu automatisé et la publicité sur le réseau de canaux de marketing digital stratégique d\'NUFOTEC<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Contenu quotidien automatisé :</strong> Conseils santé, nutrition préventive, actualités produits et remèdes maison distribués sur toutes nos plateformes</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Publicités automatisées : </strong>Campagnes ciblées nationales, régionales et internationales</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Interaction communautaire en temps réel : Assistance et collecte de commentaires 24h/24 et 7j/7 alimentées par l\'IA</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Analyses et reporting :</strong> Suit l\'engagement, l\'adoption et l\'impact ESG via des tableaux de bord en temps réel</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Impact :</strong> ChatGPT assure une sensibilisation continue, coordonnée et mesurable, transformant les communautés en canaux de marché actifs.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<h2 style=\"margin-left: -.25pt;\">4)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Impact de l\'expansion commerciale</h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Adoption rapide et reconnaissance de la marque</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Régional (EAC, COMESA, SADC)</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Contenu optimisé par l\'IA pour l\'engagement transfrontalier</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Portée internationale facilitée</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Les campagnes automatisées atteignent les distributeurs et partenaires mondiaux</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<h2 style=\"margin-left: -.25pt;\">5)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Points forts pour les investisseurs et donateurs</h2>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Traction prouvée : 235+ groupes WhatsApp, 211 500+ participants</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; line-height: 149%; mso-list: l2 level1 lfo3; margin: 0cm 0cm .85pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 149%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->L\'automatisation par IA HubSpot + ChatGPT garantit un engagement cohérent et des mises à jour quotidiennes</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Les conseils d\'experts renforcent la confiance et l\'adoption</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Les tableaux de bord en temps réel fournissent des KPI transparents et des rapports ESG</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Un système unique et coordonné permet une croissance scalable et prévisible</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 107%; margin: 0cm 0cm .15pt -.25pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">Pied de page / Phrase d\'accroche : </strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .45pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p><span style=\"font-size: 14.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Propulsée par la société NUFOTEC et HubSpot intégré à ChatGPT IA, la plateforme d\'NUFOTEC fournit du contenu quotidien automatisé, des conseils d\'experts et une promotion de produits axée sur la communauté, transformant les communautés en canaux de croissance actifs pour la santé, le développement économique et l\'expansion du marché mondial</span></p>', '<h2 style=\"margin-left: -.25pt;\">1)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Aperçu stratégique</h2>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .8pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">La plateforme de croissance digitale et d\'expansion commerciale d\'NUFOTEC centralise tous les canaux de marketing digital stratégiques, y compris les groupes WhatsApp éducatifs existants et en constante expansion, Telegram, Facebook, Instagram, TikTok, YouTube, les e-mails et le site web, dans un système unique et coordonné utilisant HubSpot Marketing Hub. Intégrée à ChatGPT IA, cette plateforme automatise le contenu quotidien, les publicités et l\'engagement communautaire, garantissant une expansion du marché scalable, mesurable et professionnelle.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Avantage pour l\'investisseur : KPI transparents, analyses en temps réel et croissance prévisible sur les marchés domestiques, régionaux et internationaux.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<h2 style=\"margin-left: -.25pt;\">2)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Engagement communautaire et d\'experts</h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">235+ groupes WhatsApp, 211 500+ participants, en expansion quotidienne</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Partenaire clé : NUFOTEC BURUNDI (EAC)</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Contenu dirigé par des experts : Des nutritionnistes, diététiciens et professionnels de santé agréés fournissent des conseils quotidiens et des informations sur :</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Maladies aiguës : ex. toux, diarrhée, infections respiratoires</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Maladies chroniques : cancer, diabète, maladies cardiovasculaires, obésité, malnutrition infantile</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Nutrition préventive, remèdes maison et agriculture biologique</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Les communautés agissent comme des canaux actifs de marketing et d\'éducation, convertissant l\'engagement en adoption de produits et en développement économique.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<h2 style=\"margin-left: -.25pt;\">3)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Services ChatGPT IA</h2>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .3pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Rôle :</strong> Pilote tout le contenu automatisé et la publicité sur le réseau de canaux de marketing digital stratégique d\'NUFOTEC<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Contenu quotidien automatisé :</strong> Conseils santé, nutrition préventive, actualités produits et remèdes maison distribués sur toutes nos plateformes</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Publicités automatisées : </strong>Campagnes ciblées nationales, régionales et internationales</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Interaction communautaire en temps réel : Assistance et collecte de commentaires 24h/24 et 7j/7 alimentées par l\'IA</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Analyses et reporting :</strong> Suit l\'engagement, l\'adoption et l\'impact ESG via des tableaux de bord en temps réel</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Impact :</strong> ChatGPT assure une sensibilisation continue, coordonnée et mesurable, transformant les communautés en canaux de marché actifs.</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<h2 style=\"margin-left: -.25pt;\">4)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Impact de l\'expansion commerciale</h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Adoption rapide et reconnaissance de la marque</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Régional (EAC, COMESA, SADC)</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Contenu optimisé par l\'IA pour l\'engagement transfrontalier</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Portée internationale facilitée</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Les campagnes automatisées atteignent les distributeurs et partenaires mondiaux</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<h2 style=\"margin-left: -.25pt;\">5)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Points forts pour les investisseurs et donateurs</h2>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Traction prouvée : 235+ groupes WhatsApp, 211 500+ participants</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; line-height: 149%; mso-list: l2 level1 lfo3; margin: 0cm 0cm .85pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 149%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->L\'automatisation par IA HubSpot + ChatGPT garantit un engagement cohérent et des mises à jour quotidiennes</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Les conseils d\'experts renforcent la confiance et l\'adoption</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Les tableaux de bord en temps réel fournissent des KPI transparents et des rapports ESG</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Un système unique et coordonné permet une croissance scalable et prévisible</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 107%; margin: 0cm 0cm .15pt -.25pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">Pied de page / Phrase d\'accroche : </strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .45pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p><span style=\"font-size: 14.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Propulsée par la société NUFOTEC et HubSpot intégré à ChatGPT IA, la plateforme d\'NUFOTEC fournit du contenu quotidien automatisé, des conseils d\'experts et une promotion de produits axée sur la communauté, transformant les communautés en canaux de croissance actifs pour la santé, le développement économique et l\'expansion du marché mondial</span></p>', '<h2 style=\"margin-left: -.25pt;\">1)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Strategic overview</h2>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .8pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">NUFOTEC\'s digital growth and business expansion platform centralizes all strategic digital marketing channels, including existing and continuously expanding WhatsApp educational groups, Telegram, Facebook, Instagram, TikTok, YouTube, emails and the website, into a single coordinated system using HubSpot Marketing Hub. Integrated with ChatGPT AI, this platform automates daily content, advertising and community engagement, ensuring scalable, measurable and professional market expansion.</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Investor advantage: Transparent KPIs, real-time analytics and predictable growth on domestic, regional and international markets.</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<h2 style=\"margin-left: -.25pt;\">2)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Community and expert engagement</h2>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">235+ WhatsApp groups, 211,500+ participants, growing daily</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Key partner: NUFOTEC BURUNDI (EAC)</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Expert-driven content: Licensed nutritionists, dietitians and healthcare professionals provide daily advice and insights on:</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Acute diseases: e.g. cough, diarrhea, respiratory infections</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Chronic diseases: cancer, diabetes, cardiovascular diseases, obesity, child malnutrition</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Preventive nutrition, home remedies and organic farming</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Communities act as active marketing and education channels, converting engagement into product adoption and economic development.</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<h2 style=\"margin-left: -.25pt;\">3)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>ChatGPT AI services</h2>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .3pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Role:</strong> Drives all automated content and advertising across NUFOTEC\'s strategic digital marketing channel network</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Automated daily content:</strong> Health tips, preventive nutrition, product news and home remedies distributed across all our platforms</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Automated advertising:</strong> Targeted national, regional and international campaigns</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Real-time community interaction: 24/7 AI-powered assistance and feedback collection</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Analytics and reporting:</strong> Tracks engagement, adoption and ESG impact via real-time dashboards</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Impact:</strong> ChatGPT ensures continuous, coordinated and measurable outreach, transforming communities into active market channels.</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<h2 style=\"margin-left: -.25pt;\">4)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Business expansion impact</h2>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Rapid adoption and brand recognition</p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Regional (EAC, COMESA, SADC)</p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->AI-optimized content for cross-border engagement</p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->International reach facilitated</p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Automated campaigns reach global distributors and partners</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<h2 style=\"margin-left: -.25pt;\">5)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Highlights for investors and donors</h2>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Proven traction: 235+ WhatsApp groups, 211,500+ participants</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; line-height: 149%; mso-list: l2 level1 lfo3; margin: 0cm 0cm .85pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 149%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->HubSpot + ChatGPT AI automation ensures consistent engagement and daily updates</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Expert advice builds trust and adoption</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Real-time dashboards provide transparent KPIs and ESG reporting</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->A single coordinated system enables scalable and predictable growth</p>\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 107%; margin: 0cm 0cm .15pt -.25pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">Footer / Tagline: </strong></p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .45pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p><span style=\"font-size: 14.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Powered by NUFOTEC and HubSpot integrated with ChatGPT AI, NUFOTEC\'s platform delivers automated daily content, expert advice and community-driven product promotion, transforming communities into active growth channels for health, economic development and global market expansion.</span></p>', '<h2 style=\"margin-left: -.25pt;\">1)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Muhtasari wa kimkakati</h2>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .8pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Jukwaa la ukuaji wa kidijitali na upanuzi wa biashara la NUFOTEC huweka katikati njia zote za kimkakati za uuzaji wa kidijitali, ikijumuisha vikundi vilivyopo na vinavyoendelea kupanuka vya WhatsApp vya kielimu, Telegram, Facebook, Instagram, TikTok, YouTube, barua pepe na tovuti, katika mfumo mmoja ulioratibiwa kwa kutumia HubSpot Marketing Hub. Kwa kuunganishwa na ChatGPT AI, jukwaa hili huweka kiotomatiki maudhui ya kila siku, matangazo na ushirikishwaji wa jamii, kuhakikisha upanuzi wa soko unaoweza kuongezeka, kupimika na wa kitaalamu.</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Faida kwa mwekezaji: KPIs za uwazi, uchambuzi wa wakati halisi na ukuaji unaotabirika kwenye masoko ya ndani, kikanda na kimataifa.</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<h2 style=\"margin-left: -.25pt;\">2)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Ushirikishwaji wa jamii na wataalam</h2>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Vikundi zaidi ya 235 vya WhatsApp, washiriki zaidi ya 211,500, vinavyoongezeka kila siku</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Mshirika mkuu: NUFOTEC BURUNDI (EAC)</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Maudhui yanayoendeshwa na wataalam: Wataalamu wa lishe wenye leseni, wataalamu wa lishe na wataalamu wa afya hutoa ushauri na maarifa ya kila siku juu ya:</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Magonjwa ya papo hapo: mfano kikohozi, kuhara, maambukizi ya kupumua</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Magonjwa sugu: kansa, kisukari, magonjwa ya moyo na mishipa, unene kupita kiasi, utapiamlo wa watoto</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Lishe ya kuzuia, tiba za nyumbani na kilimo hai</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 31.6pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Jamii hufanya kama njia hai za uuzaji na elimu, kubadilisha ushirikishwaji kuwa upitishaji wa bidhaa na maendeleo ya kiuchumi.</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<h2 style=\"margin-left: -.25pt;\">3)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Huduma za ChatGPT AI</h2>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .3pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Jukumu:</strong> Huendesha maudhui na matangazo yote kiotomatiki kwenye mtandao wa NUFOTEC wa njia za kimkakati za uuzaji wa kidijitali</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Maudhui ya kila siku kiotomatiki:</strong> Vidokezo vya afya, lishe ya kuzuia, habari za bidhaa na tiba za nyumbani zinazosambazwa kwenye majukwaa yetu yote</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Matangazo ya kiotomatiki:</strong> Kampeni zilizolengwa za kitaifa, kikanda na kimataifa</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\">Mwingiliano wa jamii kwa wakati halisi: Usaidizi na ukusanyaji wa maoni 24/7 unaoendeshwa na AI</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Uchambuzi na ripoti:</strong> Hufuatilia ushirikishwaji, upitishaji na athari za ESG kupitia dashibodi za wakati halisi</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><strong style=\"mso-bidi-font-weight: normal;\">Athari:</strong> ChatGPT inahakikisha uhamasishaji unaoendelea, ulioratibiwa na unaopimika, kubadilisha jamii kuwa njia hai za soko.</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<h2 style=\"margin-left: -.25pt;\">4)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Athari ya upanuzi wa biashara</h2>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Upitishaji wa haraka na utambuzi wa chapa</p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Kikanda (EAC, COMESA, SADC)</p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Maudhui yaliyoboreshwa na AI kwa ushirikishwaji wa kuvuka mipaka</p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Ufikiaji wa kimataifa umewezeshwa</p>\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l1 level1 lfo2; margin: 0cm 0cm .85pt 22.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Kampeni za kiotomatiki huwafikia wasambazaji na washirika wa kimataifa</p>\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<h2 style=\"margin-left: -.25pt;\">5)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Vivutio kwa wawekezaji na wafadhili</h2>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Mvutano uliothibitishwa: Vikundi zaidi ya 235 vya WhatsApp, washiriki zaidi ya 211,500</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; line-height: 149%; mso-list: l2 level1 lfo3; margin: 0cm 0cm .85pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 149%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Uwekaji kiotomatiki wa HubSpot + ChatGPT AI huhakikisha ushirikishwaji thabiti na sasisho za kila siku</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Ushauri wa wataalam hujenga uaminifu na upitishaji</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Dashibodi za wakati halisi hutoa KPIs za uwazi na ripoti za ESG</p>\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l2 level1 lfo3; margin: 0cm 0cm 7.4pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font: 7.0pt \'Times New Roman\';\"> </span></span></span><!--[endif]-->Mfumo mmoja ulioratibiwa unawezesha ukuaji unaoweza kuongezeka na unaotabirika</p>\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 107%; margin: 0cm 0cm .15pt -.25pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">Kichwa cha chini / Maneno ya mwisho: </strong></p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .45pt 0cm;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\n<p><span style=\"font-size: 14.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Inayoendeshwa na NUFOTEC na HubSpot iliyounganishwa na ChatGPT AI, jukwaa la NUFOTEC linatoa maudhui ya kila siku kiotomatiki, ushauri wa wataalam na ukuzaji wa bidhaa unaoendeshwa na jamii, kubadilisha jamii kuwa njia za ukuaji hai kwa afya, maendeleo ya kiuchumi na upanuzi wa soko la kimataifa.</span></p>', NULL, 0, '', NULL, NULL, NULL, '', 0, '2026-03-03 03:37:34', '', NULL, '2026-03-03 03:40:42', NULL, 1);
INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(237, 8, 'hero', 'Votre santé, notre priorité', 'Votre santé, notre priorité', 'Your health, our priority', 'Afya yako, kipaumbele chetu', 'Découvrez notre gamme complète de compléments alimentaires, d\'extraits de plantes et de produits biologiques, soigneusement sélectionnés pour votre bien-être quotidien.', 'Découvrez notre gamme complète de compléments alimentaires, d\'extraits de plantes et de produits biologiques, soigneusement sélectionnés pour votre bien-être quotidien.', 'Discover our complete range of food supplements, plant extracts and organic products, carefully selected for your daily well-being.', 'Gundua anuwai yetu kamili ya virutubisho vya chakula, dondoo za mimea na bidhaa za kikaboni, zilizochaguliwa kwa uangalifu kwa ustawi wako wa kila siku.', '', '', NULL, NULL, '/attachments/Sections/2026030314440469a6d7943e60c.jpg', 0, '', NULL, NULL, NULL, '', 1, '2026-03-03 14:44:04', '', NULL, '2026-03-03 14:54:41', NULL, 1),
(238, 22, 'hero', 'Vision, mission et objectifs', 'Vision, mission et objectifs', 'Vision, mission and objectives', 'Dira, dhamira na malengo', 'Vision, mission et objectifs', 'Vision, mission et objectifs', 'Vision, mission and objectives', 'Dira, dhamira na malengo', '', '', NULL, NULL, '/attachments/Sections/2026030413392069a819e840ac0.jpg', 0, '', NULL, NULL, NULL, '', 0, '2026-03-04 13:39:20', '', NULL, NULL, NULL, 1);
INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(239, 6, 'texte', 'Comités de gouvernance et personnalités', 'Comités de gouvernance et personnalités', 'Governance committees and personalities', 'Kamati za utawala na watu binafsi', 'Comités de gouvernance et personnalités', 'Comités de gouvernance et personnalités', 'Governance committees and personalities', 'Kamati za utawala na watu binafsi', '<table style=\"border-collapse: collapse; width: 103.289%; height: 2918.33px;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\"><colgroup><col style=\"width: 14.7338%;\" width=\"561\"> <col style=\"width: 37.973%;\" width=\"679\"> <col style=\"width: 1.94218%;\" width=\"28\"> <col style=\"width: 13.1265%;\" width=\"449\"> <col style=\"width: 32.2134%;\" width=\"617\"> </colgroup>\r\n<tbody>\r\n<tr style=\"height: 68.4667px;\">\r\n<td class=\"xl68\" style=\"height: 68.4667px; width: 931pt; text-align: center;\" colspan=\"2\" width=\"1240\" height=\"35\">\r\n<h2><span style=\"color: rgb(45, 194, 107);\"><strong>Governance Committees &amp; Personalities<span class=\"font7\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong></span></h2>\r\n</td>\r\n<td class=\"xl67\" style=\"width: 21pt; height: 68.4667px;\" width=\"28\">&nbsp;</td>\r\n<td class=\"xl69\" style=\"width: 800pt; text-align: center; height: 68.4667px;\" colspan=\"2\" width=\"1066\">\r\n<h2><span style=\"color: rgb(45, 194, 107);\">Departments &amp; Responsibilities<span style=\"mso-spacerun: yes;\">&nbsp;</span></span></h2>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 33.3333px;\">\r\n<td class=\"xl71\" style=\"height: 33.3333px;\" height=\"33\">&nbsp;</td>\r\n<td class=\"xl66\" style=\"height: 33.3333px;\">&nbsp;</td>\r\n<td class=\"xl70\" style=\"height: 33.3333px;\">&nbsp;</td>\r\n<td class=\"xl82\" style=\"height: 33.3333px;\">&nbsp;</td>\r\n<td class=\"xl72\" style=\"height: 33.3333px;\">&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 60px;\">\r\n<td class=\"xl77\" style=\"height: 60px;\" height=\"60\"><strong><span style=\"color: rgb(230, 126, 35);\">Executive Management Committee EMC</span></strong></td>\r\n<td class=\"xl76\" style=\"height: 60px;\"><strong><em><span class=\"font6\">&nbsp;Strategic planning &amp; policy approval<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;</span></span></em></strong></td>\r\n<td class=\"xl70\" style=\"height: 60px;\">&nbsp;</td>\r\n<td class=\"xl83\" style=\"height: 60px;\"><span style=\"color: rgb(53, 152, 219);\"><strong>Production Department<span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></td>\r\n<td class=\"xl73\" style=\"height: 60px;\"><strong><em>&uuml;<span class=\"font5\"> Executes manufacturing (extraction, formulation, packaging)<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;</span></span></em></strong></td>\r\n</tr>\r\n<tr style=\"height: 60px;\">\r\n<td class=\"xl78\" style=\"height: 60px;\" height=\"60\">&nbsp;</td>\r\n<td class=\"xl76\" style=\"height: 60px;\"><strong><em><span class=\"font6\">&nbsp;Oversees departmental coordination</span></em></strong></td>\r\n<td class=\"xl70\" style=\"height: 60px;\">&nbsp;</td>\r\n<td class=\"xl82\" style=\"height: 60px;\">&nbsp;</td>\r\n<td class=\"xl73\" style=\"height: 60px;\"><strong><em>&uuml;<span class=\"font5\"> Maintains batch records, GMP hygiene<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;</span></span></em></strong></td>\r\n</tr>\r\n<tr style=\"height: 32.6667px;\">\r\n<td class=\"xl78\" style=\"height: 32.6667px;\" height=\"33\">&nbsp;</td>\r\n<td class=\"xl76\" style=\"height: 32.6667px;\"><strong><em><span class=\"font6\">&nbsp;Budget &amp; investment decisions</span></em></strong></td>\r\n<td class=\"xl70\" style=\"height: 32.6667px;\">&nbsp;</td>\r\n<td class=\"xl82\" style=\"height: 32.6667px;\">&nbsp;</td>\r\n<td class=\"xl73\" style=\"height: 32.6667px;\"><strong><em>&uuml;<span class=\"font5\"> Manages equipment operations</span></em></strong></td>\r\n</tr>\r\n<tr style=\"height: 33.3333px;\">\r\n<td class=\"xl78\" style=\"height: 33.3333px;\" height=\"33\">&nbsp;</td>\r\