INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(240, 23, 'hero', 'BIENVENUE', 'BIENVENUE', 'WELCOME', 'KARIBU', 'Bon choix pour devenir notre intermédiaire en introduction de capitaux', 'Bon choix pour devenir notre intermédiaire en introduction de capitaux', 'Good choice to become our capital introduction intermediary', 'Chaguo nzuri kuwa mpatanishi wetu wa utangulizi wa mtaji', '', '', NULL, NULL, '/attachments/Sections/2026030418202369a85bc772720.jpg', 0, '', NULL, NULL, NULL, '', 1, '2026-03-04 18:20:24', '', NULL, NULL, NULL, 1),
(241, 23, 'texte', 'Formulaire de manifestation d\'intérêt', 'Formulaire de manifestation d\'intérêt', 'Expression of interest form', 'Fomu ya kuelezea nia', 'Formulaire de manifestation d\'intérêt', 'Formulaire de manifestation d\'intérêt', 'Expression of interest form', 'Fomu ya kuelezea nia', '<p>AFRICAN GREEN FARMERS LTD (NUFOTEC) invite les intermédiaires en capitaux qualifiés et conformes à enregistrer leur intérêt à soutenir la mobilisation de financements stratégiques pour ses programmes intégrés de développement agro-industriel, de bioéconomie et phytopharmaceutique.</p>\r\n<p>Cet enregistrement est adressé à AFRICAN GREEN FARMERS LTD en tant qu\'entité principale.</p>\r\n<p>La soumission de ce formulaire ne constitue pas un mandat, une exclusivité ou un engagement juridiquement contraignant. Toute collaboration est soumise à une diligence raisonnable et à la signature d\'un accord formel.</p>', '<p>AFRICAN GREEN FARMERS LTD (NUFOTEC) invite les intermédiaires en capitaux qualifiés et conformes à enregistrer leur intérêt à soutenir la mobilisation de financements stratégiques pour ses programmes intégrés de développement agro-industriel, de bioéconomie et phytopharmaceutique.</p>\r\n<p>Cet enregistrement est adressé à AFRICAN GREEN FARMERS LTD en tant qu\'entité principale.</p>\r\n<p>La soumission de ce formulaire ne constitue pas un mandat, une exclusivité ou un engagement juridiquement contraignant. Toute collaboration est soumise à une diligence raisonnable et à la signature d\'un accord formel.</p>', '<p>AFRICAN GREEN FARMERS LTD (NUFOTEC) invites qualified and compliant capital intermediaries to register their interest in supporting strategic fundraising for its integrated agro-industrial, bioeconomy and phytopharmaceutical development programs.</p>\n<p>This registration is addressed to AFRICAN GREEN FARMERS LTD as the lead entity.</p>\n<p>Submission of this form does not constitute a mandate, exclusivity or legally binding commitment. Any collaboration is subject to due diligence and the signing of a formal agreement.</p>', '<p>AFRICAN GREEN FARMERS LTD (NUFOTEC) inakaribisha wapatanishi wa mtaji waliohitimu na wanaofuata kanuni kusajili nia yao ya kusaidia ufadhili wa kimkakati kwa programu zake zilizojumuishwa za maendeleo ya kilimo-viwanda, uchumi wa kibayolojia na dawa za mimea.</p>\n<p>Usajili huu unaelekezwa kwa AFRICAN GREEN FARMERS LTD kama shirika linaloongoza.</p>\n<p>Uwasilishaji wa fomu hii haujumuishi mamlaka, upekee au dhamira ya kisheria inayofunga. Ushirikiano wowote unategemea uchunguzi wa kina na kusainiwa kwa makubaliano rasmi.</p>', NULL, 0, '', NULL, NULL, NULL, '', 1, '2026-03-04 18:21:33', '', NULL, NULL, NULL, 1),
(242, 24, 'hero', 'BIENVENUE', 'BIENVENUE', 'WELCOME', 'KARIBU', 'INVESTISSEZ EN NOUS OU DEVENEZ NOTRE COURTIER CONTRACTUEL DÈS AUJOURD\'HUI !?', 'INVESTISSEZ EN NOUS OU DEVENEZ NOTRE COURTIER CONTRACTUEL DÈS AUJOURD\'HUI !?', 'INVEST IN US OR BECOME OUR CONTRACTUAL BROKER TODAY!?', 'WEKEZA KWETU AU KUWA DALALI WETU WA KANDARASI LEO!?', '', '', NULL, NULL, '/attachments/Sections/2026030421081669a88320c4170.jpg', 0, '', NULL, NULL, NULL, '', 0, '2026-03-04 21:08:16', '', NULL, NULL, NULL, 1);
