INSERT INTO `workflow_categories` (`id_workflow`, `id_categorie`, `etape_ordre`, `nom_etape`, `description_etape`, `type_etape`, `responsable_role`, `delai_heures`, `est_obligatoire`, `notification_email`, `icone_etape`, `couleur_etape`, `est_active`, `created_at`, `updated_at`) VALUES
(7, 1, 1, 'CRUDE AND PURIFIED EXTRACTS PROCESSING WORKFLOW: ', '<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -13.45pt; line-height: 103%; mso-list: l0 level1 lfo1; margin: 0cm 0cm .7pt 30.15pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%; font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]--> <span style=\"line-height: 103%;\">TCAMs (Traditional, Complementary, and Alternative Medicines) </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -13.45pt; line-height: 103%; mso-list: l0 level1 lfo1; margin: 0cm 0cm .7pt 30.15pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><!-- [if !supportLists]--><span style=\"line-height: 103%; font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]--><span style=\"line-height: 103%;\">Nutraceuticals/Food Supplements </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -13.45pt; line-height: 103%; mso-list: l0 level1 lfo1; margin: 0cm 0cm .7pt 30.15pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><!-- [if !supportLists]--><span style=\"line-height: 103%; font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]--><span style=\"line-height: 103%;\">Phytomedicines </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -13.45pt; line-height: 103%; mso-list: l0 level1 lfo1; margin: 0cm 0cm .7pt 30.15pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><!-- [if !supportLists]--><span style=\"line-height: 103%; font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]--><span style=\"line-height: 103%;\">Phytopharmaceuticals </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 107%;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">With our customized, fully integrated and automated Turnkey Ultrasound-Assisted Extraction (UAE), Capsule Production, Tableting and Packaging Line System: </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 107%;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 1: Papaya Leaf Powder reception and inspection </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 2: Degreasing </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 119.95pt .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 3: Extraction of target bioactive compounds using specific organic solvent Step 4: Concentration </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 5: Chromatographic purification </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 6: Vacuum drying </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 7: Micronization and ultrasonic vibratory sieving<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 8: Anti-cracking agent aseptic incorporation </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 9: Initial profiling and standardization </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 10: Capsule processing/tableting </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 11: Bottle filling, capping and sealing </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 12: Instructional labeling </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 13: Cartoning and leaflet inserting </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 14: Case packaging </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 15: Post-packaging High Pressure Processing (HPP) Optimization (Non-thermal sterilization) </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt 